// A simple placeholder for future pages
const PlaceholderPage = ({ title, phase }: { title: string, phase: string }) => (
  <div className="flex flex-col items-center justify-center h-[60vh] text-center p-8 bg-white rounded-xl border border-dashed border-slate-300">
    <div className="p-4 bg-slate-100 rounded-full mb-4">
      <Construction size={48} className="text-slate-400" />
    </div>
    <h2 className="text-xl font-bold text-slate-900 mb-2">{title}</h2>
    <p className="text-slate-500 max-w-md">
      Bu modül henüz aktif değil. Proje planına göre <strong>{phase}</strong> kapsamında geliştirilecektir.
    </p>
  </div>
);

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);

  // Navigation State
  // Note: Using simple state-based routing for this demo instead of react-router-dom 
  // to minimize dependencies and keep it single-file logic where possible for this strict environment.
  // In a full production app, I would use React Router.
  const [currentPage, setCurrentPage] = useState('/');

  // Check for stored session on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('emlak_user');
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (e) {
        localStorage.removeItem('emlak_user');
      }
    }
  }, []);

  const handleLogin = (newUser: User) => {
    setUser(newUser);
    localStorage.setItem('emlak_user', JSON.stringify(newUser));
    setCurrentPage('/');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('emlak_user');
    setCurrentPage('/');
  };

  const renderPage = () => {
    switch (currentPage) {
      case '/':
        return user ? <Dashboard user={user} /> : null;
      case '/consultants':
        return <PlaceholderPage title="Danışman Yönetimi" phase="FAZA 1 (2. Hafta)" />;
      case '/transactions':
        return <PlaceholderPage title="Gelir & İşlemler" phase="FAZA 2 (3. Hafta)" />;
      case '/expenses':
        return <PlaceholderPage title="Gider Takibi" phase="FAZA 4 (5. Hafta)" />;
      case '/reports':
        return <PlaceholderPage title="Raporlar & Dashboard" phase="FAZA 6 (7-8. Hafta)" />;
      case '/settings':
        return <PlaceholderPage title="Ayarlar" phase="Gelecek Plan" />;
      default:
        return <Dashboard user={user!} />;
    }
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout}
      currentPage={currentPage}
      onNavigate={setCurrentPage}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

