          <h1 className="text-2xl font-bold text-slate-900">Gider Yönetimi</h1>
          <p className="text-slate-500">Ofis harcamalarını ve ortak ödemelerini kaydedin.</p>
        </div>
        <button
          onClick={handleOpenModal}
          className="flex items-center justify-center gap-2 bg-rose-600 hover:bg-rose-700 text-white px-4 py-2.5 rounded-lg font-medium transition-colors shadow-sm"
        >
          <Plus size={20} />
          <span>Yeni Gider Ekle</span>
        </button>
      </div>

      {/* Summary Stats */}
      <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
         <div className="flex items-center gap-4">
            <div className="p-3 bg-rose-50 text-rose-600 rounded-full">
                <Receipt size={24} />
            </div>
            <div>
                <p className="text-sm font-medium text-slate-500">Toplam Gider (Görüntülenen)</p>
                <h2 className="text-3xl font-bold text-slate-900">{formatCurrency(totalExpenses)}</h2>
            </div>
         </div>
         <div className="hidden sm:block text-right">
             <p className="text-xs text-slate-400">Bu veriler ortak harcama<br/>dengesini etkiler.</p>
         </div>
      </div>

      {/* Filter Bar */}
      <div className="flex gap-4">
        <div className="relative flex-1">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
            <Search size={20} />
