         <div className="flex items-center gap-4">
            <div className="p-3 bg-rose-50 text-rose-600 rounded-full">
                <Receipt size={24} />
            </div>
            <div>
                <p className="text-sm font-medium text-slate-500">Toplam Gider</p>
                <h2 className="text-3xl font-bold text-slate-900">{formatCurrency(totalExpenses)}</h2>
            </div>
         </div>
         <div className="hidden sm:block text-right">
             <p className="text-xs text-slate-400">Görüntülenen veriler üzerinden<br/>hesaplanmıştır.</p>
         </div>
      </div>

      {/* Breakdown Cards (Who Paid What) */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {/* Altan Card */}
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-center justify-between">
            <div>
                <p className="text-xs font-bold text-indigo-500 uppercase tracking-wide mb-1">Altan Ödedi</p>
                <p className="text-xl font-bold text-indigo-900">{formatCurrency(totalAltan)}</p>
            </div>
            <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg">
                <Wallet size={20} />
            </div>
        </div>

        {/* Suat Card */}
        <div className="bg-violet-50 border border-violet-100 p-4 rounded-xl flex items-center justify-between">
            <div>
                <p className="text-xs font-bold text-violet-500 uppercase tracking-wide mb-1">Suat Ödedi</p>
                <p className="text-xl font-bold text-violet-900">{formatCurrency(totalSuat)}</p>
            </div>
            <div className="p-2 bg-violet-100 text-violet-600 rounded-lg">
                <Wallet size={20} />
            </div>
        </div>

        {/* Office Card */}
        <div className="bg-slate-50 border border-slate-200 p-4 rounded-xl flex items-center justify-between">
            <div>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-1">Ofis Kasasından</p>
                <p className="text-xl font-bold text-slate-900">{formatCurrency(totalOffice)}</p>
            </div>
            <div className="p-2 bg-slate-200 text-slate-600 rounded-lg">
                <Building2 size={20} />
            </div>
        </div>
      </div>

      {/* Search and Filter Bar */}
      <div className="space-y-4">
        <div className="flex gap-4">
          <div className="relative flex-1">
