const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);

  // Navigation State
  const [currentPage, setCurrentPage] = useState('/');

  // Check for stored session on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('emlak_user');
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (e) {
        localStorage.removeItem('emlak_user');
      }
    }
  }, []);

  const handleLogin = (newUser: User) => {
    setUser(newUser);
    localStorage.setItem('emlak_user', JSON.stringify(newUser));
    setCurrentPage('/');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('emlak_user');
    setCurrentPage('/');
  };

  const renderPage = () => {
    switch (currentPage) {
      case '/':
        return user ? <Dashboard user={user} /> : null;
      case '/consultants':
        return <Consultants />;
      case '/personnel':
        return <PersonnelPage />;
      case '/transactions':
        return <Transactions />;
      case '/expenses':
        return <Expenses />;
      case '/reports':
        return <Reports />;
      case '/settings':
        return <PlaceholderPage title="Ayarlar" phase="Gelecek Plan" />;
      default:
        return <Dashboard user={user!} />;
    }
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout}
      currentPage={currentPage}
      onNavigate={setCurrentPage}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

