                        <span className="text-xs font-semibold uppercase">Ödeyen</span>
                    </div>
                    <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-bold border ${getPayerLabel(selectedExpense.paidBy).color}`}>
                        {getPayerLabel(selectedExpense.paidBy).label}
                    </span>
                </div>
            </div>

            <div className="space-y-2">
                <div className="flex items-center gap-2 text-slate-500">
                    <Tag size={16} />
                    <span className="text-xs font-semibold uppercase">Kategori</span>
                </div>
                <div className="p-3 border border-slate-200 rounded-lg flex items-center gap-2 bg-white">
                    <span className={`w-3 h-3 rounded-full ${getCategoryStyle(selectedExpense.category).split(' ')[0]}`}></span>
                    <span className="font-medium text-slate-700">{getCategoryLabel(selectedExpense.category)}</span>
                </div>
            </div>

            <div className="space-y-2">
                 <div className="flex items-center gap-2 text-slate-500">
                    <FileText size={16} />
                    <span className="text-xs font-semibold uppercase">Açıklama</span>
                </div>
                <div className="p-4 border border-slate-200 rounded-lg bg-slate-50/50 text-slate-700 min-h-[80px]">
                    {selectedExpense.description}
                </div>
            </div>

            {/* Notes Display - NEW */}
            {selectedExpense.notes && (
                <div className="space-y-2">
                    <div className="flex items-center gap-2 text-slate-500">
                        <StickyNote size={16} />
                        <span className="text-xs font-semibold uppercase">Notlar</span>
                    </div>
                    <div className="p-4 border border-amber-200 rounded-lg bg-amber-50 text-slate-700 text-sm">
                        {selectedExpense.notes}
                    </div>
                </div>
            )}

            <div className="pt-4 flex gap-3">
                <button
                    onClick={() => handleDelete(selectedExpense.id)}
                    className="flex-1 py-3 bg-red-50 hover:bg-red-100 text-red-700 font-medium rounded-lg transition-colors flex items-center justify-center gap-2"
                >
                    <Trash2 size={18} />
                    Sil
                </button>
                <button
                    onClick={() => {
                        setIsViewModalOpen(false);
                        handleOpenModal(selectedExpense);
                    }}
                    className="flex-1 py-3 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-medium rounded-lg transition-colors flex items-center justify-center gap-2"
                >
                    <Edit size={18} />
                    Düzenle
                </button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default Expenses;

// --- KULLANICI & ROL ŞEMASI ---
export enum UserRole {
  PARTNER = 'ORTAK', // Altan, Suat
  ACCOUNTANT = 'MUHASEBE', // Nalan
}

export interface User {
  id: string;
  username: string;
  name: string;
  role: UserRole;
}

// --- DANIŞMAN ŞEMASI (Faz 1) ---
export interface Consultant {
  id: string;
  fullName: string;
  phoneNumber: string;
  commissionRate: number; // Yüzde olarak (örn: 50)
  startDate: string; // ISO Date
  isActive: boolean;
}

// --- İŞLEM & GELİR ŞEMASI (Faz 2 & 3) ---
export enum TransactionType {
  SALE = 'SATIS',
  RENT = 'KIRALAMA',
}

export enum PaymentStatus {
  PENDING = 'BEKLIYOR',
  PAID = 'ODENDI', // İmzalandı / Kapandı
}

export interface Transaction {
  id: string;
  propertyName: string; // Serbest metin
  type: TransactionType;
  customerName: string;
  consultantId: string; // Consultant FK
  date: string; // ISO Date
  totalRevenue: number; // Toplam Ciro

  // Otomatik Hesaplanan Alanlar
  officeRevenue: number; // Ciro * (1 - Danışman Oranı) veya direkt Ofise Kalan
  consultantShare: number; // Ciro * Danışman Oranı
  partnerShareAltan: number; // Ofise Kalan / 2
  partnerShareSuat: number; // Ofise Kalan / 2

  // Faz 3: Hakediş Durumu
  paymentStatus: PaymentStatus;
}

// --- GİDER ŞEMASI (Faz 4) ---
export enum ExpenseCategory {
  OFFICE_SUPPLIES = 'OFIS_MALZEMELERI',
  RENT = 'KIRA',
  MARKETING = 'PAZARLAMA',
  PERSONNEL = 'PERSONEL_MAAS',
  UTILITIES = 'FATURALAR',
  FOOD = 'YEMEK',
  OTHER = 'DIGER',
}

export enum Payer {
  ALTAN = 'ALTAN',
  SUAT = 'SUAT',
  OFFICE = 'OFIS_KASASI',
}

export interface Expense {
  id: string;
  category: ExpenseCategory;
  amount: number;
  date: string;
  description: string;
  paidBy: Payer;
  notes?: string;
}

// --- MAAŞ & PERSONEL ŞEMASI (Faz 5) ---
export interface Personnel {
  id: string;
  fullName: string;
  role: string; // Örn: Ofis Asistanı, Çaycı, Temizlik
  monthlySalary: number;
  startDate: string;
  isActive: boolean;
}

export interface SalaryPayment {
  id: string;
  personnelId: string;
  amount: number;
  date: string;
  period: string; // "2023-10" (Yıl-Ay)
  isPaid: boolean;
}

// --- LOG SİSTEMİ (Güvenlik) ---
export interface SystemLog {
  id: string;
  date: string; // ISO Timestamp
  user: string; // User Name
  action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE' | 'RESET';
  module: 'EXPENSE' | 'TRANSACTION' | 'SYSTEM' | 'PERSONNEL' | 'CONSULTANT';
  description: string;
}

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Consultants from './pages/Consultants';
import Transactions from './pages/Transactions';
import Expenses from './pages/Expenses';
import PersonnelPage from './pages/Personnel';
import Reports from './pages/Reports';
import Settings from './pages/Settings';
import { User } from './types';

const App: React.FC = () => {
  // Auth State
  const [user, setUser] = useState<User | null>(null);

  // Navigation State
  const [currentPage, setCurrentPage] = useState('/');

  // Check for stored session on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('emlak_user');
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (e) {
        localStorage.removeItem('emlak_user');
      }
    }
  }, []);

  const handleLogin = (newUser: User) => {
    setUser(newUser);
    localStorage.setItem('emlak_user', JSON.stringify(newUser));
    setCurrentPage('/');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('emlak_user');
    setCurrentPage('/');
  };

  const renderPage = () => {
    if (!user) return <Login onLogin={handleLogin} />;

    switch (currentPage) {
      case '/':
        return <Dashboard user={user} />;
      case '/consultants':
        return <Consultants currentUser={user} />;
      case '/personnel':
        return <PersonnelPage currentUser={user} />;
      case '/transactions':
        return <Transactions currentUser={user} />;
      case '/expenses':
        return <Expenses currentUser={user} />;
      case '/reports':
        return <Reports />;
      case '/settings':
        return <Settings currentUser={user} />;
      default:
        return <Dashboard user={user} />;
    }
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout}
      currentPage={currentPage}
      onNavigate={setCurrentPage}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Consultant, User, SystemLog } from '../types';
import { INITIAL_CONSULTANTS } from '../constants';
import Modal from '../components/Modal';
import { Plus, Search, Edit2, Phone, Calendar, Percent, UserCheck, UserX } from 'lucide-react';

interface ConsultantsProps {
  currentUser: User;
}

const Consultants: React.FC<ConsultantsProps> = ({ currentUser }) => {
  const [consultants, setConsultants] = useState<Consultant[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Consultant>>({
    fullName: '',
    phoneNumber: '',
    commissionRate: 50,
    startDate: new Date().toISOString().split('T')[0],
    isActive: true,
  });

  // Load data on mount
  useEffect(() => {
    const stored = localStorage.getItem('emlak_consultants');
    if (stored) {
      setConsultants(JSON.parse(stored));
    } else {
      setConsultants(INITIAL_CONSULTANTS);
      localStorage.setItem('emlak_consultants', JSON.stringify(INITIAL_CONSULTANTS));
    }
  }, []);

  // Save data on change
  useEffect(() => {
    if (consultants.length > 0) {
      localStorage.setItem('emlak_consultants', JSON.stringify(consultants));
    }
  }, [consultants]);

  // LOGGING HELPER
  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE', description: string) => {
    try {
      const newLog: SystemLog = {
        id: Date.now().toString(),
        date: new Date().toISOString(),
        user: currentUser.name,
        action: action,
        module: 'CONSULTANT',
        description: description
      };
      const storedLogs = localStorage.getItem('emlak_logs');
      let logs = storedLogs ? JSON.parse(storedLogs) : [];
      if (!Array.isArray(logs)) logs = [];
      localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
    } catch (e) {
      console.error("Logging failed", e);
    }
  };

  const handleOpenModal = (consultant?: Consultant) => {
    if (consultant) {
      setEditingId(consultant.id);
      setFormData({ ...consultant });
    } else {
      setEditingId(null);
      setFormData({
        fullName: '',
        phoneNumber: '',
        commissionRate: 50,
        startDate: new Date().toISOString().split('T')[0],
        isActive: true,
      });
    }
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      setConsultants(prev => prev.map(c => 
        c.id === editingId ? { ...c, ...formData } as Consultant : c
      ));
      logAction('UPDATE', `Danışman Bilgisi Güncellendi: ${formData.fullName}`);
    } else {
      const newConsultant: Consultant = {
        id: Date.now().toString(),
        ...formData as Omit<Consultant, 'id'>
      };
      setConsultants(prev => [...prev, newConsultant]);
      logAction('CREATE', `Yeni Danışman Eklendi: ${newConsultant.fullName} (Oran: %${newConsultant.commissionRate})`);
    }
    handleCloseModal();
  };

  const filteredConsultants = consultants.filter(c => 
    c.fullName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.phoneNumber.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Danışman Yönetimi</h1>
          <p className="text-slate-500">Ekip üyelerini ve komisyon oranlarını yönetin.</p>
        </div>
        <button
          onClick={() => handleOpenModal()}
          className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium transition-colors shadow-sm"
        >
          <Plus size={20} />
          <span>Yeni Danışman</span>
        </button>
      </div>

      {/* Filter Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
          <Search size={20} />
        </div>
        <input
          type="text"
          placeholder="İsim veya telefon ile ara..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-shadow"
        />
      </div>

      {/* Grid List */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredConsultants.map((consultant) => (
          <div 
            key={consultant.id} 
            className={`
              group relative bg-white rounded-xl border transition-all duration-200 hover:shadow-md
              ${consultant.isActive ? 'border-slate-200' : 'border-slate-100 bg-slate-50 opacity-75'}
            `}
          >
            {/* Status Badge */}
            <div className="absolute top-4 right-4">
              <span className={`
                inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border
                ${consultant.isActive 
                  ? 'bg-green-50 text-green-700 border-green-100' 
                  : 'bg-slate-100 text-slate-600 border-slate-200'}
              `}>
                {consultant.isActive ? 'Aktif' : 'Pasif'}
              </span>
            </div>

            <div className="p-6">
              {/* Profile Header */}
              <div className="flex items-start gap-4 mb-6">
                <div className={`
                  w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold
                  ${consultant.isActive 
                    ? 'bg-indigo-50 text-indigo-600' 
                    : 'bg-slate-200 text-slate-500'}
                `}>
                  {consultant.fullName.charAt(0)}
                </div>
                <div>
                  <h3 className="font-bold text-slate-900 line-clamp-1">{consultant.fullName}</h3>
                  <div className="flex items-center gap-1.5 text-slate-500 text-sm mt-1">
                    <Calendar size={14} />
                    <span>{new Date(consultant.startDate).toLocaleDateString('tr-TR')}</span>
                  </div>
                </div>
              </div>

              {/* Details */}
              <div className="space-y-3">
                <div className="flex items-center justify-between text-sm">
                  <div className="flex items-center gap-2 text-slate-600">
                    <Phone size={16} className="text-slate-400" />
                    <span>Telefon</span>
                  </div>
                  <span className="font-medium text-slate-900">{consultant.phoneNumber}</span>
                </div>

                <div className="flex items-center justify-between text-sm">
                  <div className="flex items-center gap-2 text-slate-600">
                    <Percent size={16} className="text-slate-400" />
                    <span>Komisyon Oranı</span>
                  </div>
                  <span className="font-bold text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded">
                    %{consultant.commissionRate}
                  </span>
                </div>
              </div>

              {/* Action Button */}
              <div className="mt-6 pt-4 border-t border-slate-100">
                <button
                  onClick={() => handleOpenModal(consultant)}
                  className="w-full flex items-center justify-center gap-2 text-sm font-medium text-slate-600 hover:text-indigo-600 py-2 rounded-lg hover:bg-slate-50 transition-colors"
                >
                  <Edit2 size={16} />
                  Profili Düzenle
                </button>
              </div>
            </div>
          </div>
        ))}

        {/* Empty State */}
        {filteredConsultants.length === 0 && (
          <div className="col-span-full flex flex-col items-center justify-center py-12 text-center text-slate-500 bg-slate-50 rounded-xl border border-dashed border-slate-200">
            <UserX size={48} className="text-slate-300 mb-4" />
            <p className="font-medium">Kayıtlı danışman bulunamadı.</p>
            <p className="text-sm mt-1">Yeni bir danışman ekleyerek başlayın.</p>
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      <Modal
        isOpen={isModalOpen}
        onClose={handleCloseModal}
        title={editingId ? 'Danışman Düzenle' : 'Yeni Danışman Ekle'}
      >
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Ad Soyad</label>
            <input
              type="text"
              required
              value={formData.fullName}
              onChange={e => setFormData({...formData, fullName: e.target.value})}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
              placeholder="Örn: Ahmet Yılmaz"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Telefon</label>
              <input
                type="tel"
                required
                value={formData.phoneNumber}
                onChange={e => setFormData({...formData, phoneNumber: e.target.value})}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
                placeholder="05XX XXX XX XX"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Komisyon Oranı (%)</label>
              <input
                type="number"
                min="0"
                max="100"
                required
                value={formData.commissionRate}
                onChange={e => setFormData({...formData, commissionRate: Number(e.target.value)})}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">İşe Başlama Tarihi</label>
            <input
              type="date"
              required
              value={formData.startDate}
              onChange={e => setFormData({...formData, startDate: e.target.value})}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
            />
          </div>

          {editingId && (
            <div className="pt-2">
              <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg cursor-pointer hover:bg-slate-50">
                <div className={`
                  w-5 h-5 rounded flex items-center justify-center border
                  ${formData.isActive ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300 bg-white'}
                `}>
                  {formData.isActive && <UserCheck size={14} className="text-white" />}
                </div>
                <input
                  type="checkbox"
                  className="hidden"
                  checked={formData.isActive}
                  onChange={e => setFormData({...formData, isActive: e.target.checked})}
                />
                <div className="flex-1">
                  <span className="text-sm font-medium text-slate-700">Danışman Aktif</span>
                  <p className="text-xs text-slate-500">Pasif duruma alınan danışmanlar yeni işlemlerde seçilemez.</p>
                </div>
              </label>
            </div>
          )}

          <div className="pt-4 flex gap-3">
            <button
              type="button"
              onClick={handleCloseModal}
              className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 font-medium rounded-lg transition-colors"
            >
              İptal
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-2 text-white bg-indigo-600 hover:bg-indigo-700 font-medium rounded-lg transition-colors"
            >
              {editingId ? 'Değişiklikleri Kaydet' : 'Danışmanı Ekle'}
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Consultants;

import React, { useState, useEffect } from 'react';
import { Personnel, SalaryPayment, Expense, ExpenseCategory, Payer, User as UserType, SystemLog } from '../types';
import { INITIAL_PERSONNEL, INITIAL_SALARY_PAYMENTS, INITIAL_EXPENSES } from '../constants';
import Modal from '../components/Modal';
import { Plus, Search, User, Briefcase, Calendar, DollarSign, Wallet, History, AlertCircle, CheckCircle2 } from 'lucide-react';

interface PersonnelProps {
  currentUser: UserType;
}

const PersonnelPage: React.FC<PersonnelProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'EMPLOYEES' | 'PAYROLL'>('EMPLOYEES');
  const [personnel, setPersonnel] = useState<Personnel[]>([]);
  const [payments, setPayments] = useState<SalaryPayment[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  // Modal States
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Personnel | null>(null);

  // Filter State
  const [searchTerm, setSearchTerm] = useState('');

  // Form States
  const [employeeForm, setEmployeeForm] = useState<Partial<Personnel>>({
    fullName: '',
    role: '',
    monthlySalary: 0,
    startDate: new Date().toISOString().split('T')[0],
    isActive: true,
  });

  const [paymentForm, setPaymentForm] = useState({
    personnelId: '',
    amount: 0,
    date: new Date().toISOString().split('T')[0],
    period: new Date().toISOString().slice(0, 7), // "YYYY-MM"
  });

  // Load Data
  useEffect(() => {
    const storedPersonnel = localStorage.getItem('emlak_personnel');
    if (storedPersonnel) {
      setPersonnel(JSON.parse(storedPersonnel));
    } else {
      setPersonnel(INITIAL_PERSONNEL);
      localStorage.setItem('emlak_personnel', JSON.stringify(INITIAL_PERSONNEL));
    }

    const storedPayments = localStorage.getItem('emlak_salary_payments');
    if (storedPayments) {
      setPayments(JSON.parse(storedPayments));
    } else {
      setPayments(INITIAL_SALARY_PAYMENTS);
      localStorage.setItem('emlak_salary_payments', JSON.stringify(INITIAL_SALARY_PAYMENTS));
    }

    const storedExpenses = localStorage.getItem('emlak_expenses');
    if (storedExpenses) {
      setExpenses(JSON.parse(storedExpenses));
    } else {
      setExpenses(INITIAL_EXPENSES);
    }
  }, []);

  // Save Data
  useEffect(() => {
    if (personnel.length > 0) localStorage.setItem('emlak_personnel', JSON.stringify(personnel));
  }, [personnel]);

  useEffect(() => {
    if (payments.length > 0) localStorage.setItem('emlak_salary_payments', JSON.stringify(payments));
  }, [payments]);

  useEffect(() => {
    if (expenses.length > 0) localStorage.setItem('emlak_expenses', JSON.stringify(expenses));
  }, [expenses]);

  // LOGGING HELPER
  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE', description: string) => {
    try {
      const newLog: SystemLog = {
        id: Date.now().toString(),
        date: new Date().toISOString(),
        user: currentUser.name,
        action: action,
        module: 'PERSONNEL',
        description: description
      };
      const storedLogs = localStorage.getItem('emlak_logs');
      let logs = storedLogs ? JSON.parse(storedLogs) : [];
      if (!Array.isArray(logs)) logs = [];
      localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
    } catch (e) {
      console.error("Logging failed", e);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const handleOpenEmployeeModal = (emp?: Personnel) => {
    if (emp) {
      setEditingEmployee(emp);
      setEmployeeForm({ ...emp });
    } else {
      setEditingEmployee(null);
      setEmployeeForm({
        fullName: '',
        role: '',
        monthlySalary: 0,
        startDate: new Date().toISOString().split('T')[0],
        isActive: true,
      });
    }
    setIsEmployeeModalOpen(true);
  };

  const handleEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingEmployee) {
      setPersonnel(prev => prev.map(p => p.id === editingEmployee.id ? { ...p, ...employeeForm } as Personnel : p));
      logAction('UPDATE', `Personel Bilgisi Güncellendi: ${employeeForm.fullName}`);
    } else {
      const newEmp: Personnel = {
        id: Date.now().toString(),
        ...employeeForm as Omit<Personnel, 'id'>
      };
      setPersonnel(prev => [...prev, newEmp]);
      logAction('CREATE', `Yeni Personel Eklendi: ${newEmp.fullName} (${newEmp.role})`);
    }
    setIsEmployeeModalOpen(false);
  };

  const handleOpenPaymentModal = () => {
    const firstEmp = personnel.find(p => p.isActive);
    setPaymentForm({
      personnelId: firstEmp ? firstEmp.id : '',
      amount: firstEmp ? firstEmp.monthlySalary : 0,
      date: new Date().toISOString().split('T')[0],
      period: new Date().toISOString().slice(0, 7),
    });
    setIsPaymentModalOpen(true);
  };

  const handlePaymentSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const selectedEmp = personnel.find(p => p.id === paymentForm.personnelId);
    if (!selectedEmp) return;

    const newPayment: SalaryPayment = {
        id: `sp-${Date.now()}`,
        personnelId: paymentForm.personnelId,
        amount: Number(paymentForm.amount),
        date: paymentForm.date,
        period: paymentForm.period,
        isPaid: true
    };
    setPayments(prev => [newPayment, ...prev]);

    const newExpense: Expense = {
        id: `exp-${Date.now()}`,
        category: ExpenseCategory.PERSONNEL,
        amount: Number(paymentForm.amount),
        date: paymentForm.date,
        description: `${paymentForm.period} Maaş Ödemesi - ${selectedEmp.fullName}`,
        paidBy: Payer.OFFICE
    };
    setExpenses(prev => [newExpense, ...prev]);

    logAction('APPROVE', `Maaş Ödemesi Yapıldı: ${selectedEmp.fullName} (${paymentForm.period} Dönemi)`);
    setIsPaymentModalOpen(false);
    alert('Maaş ödemesi kaydedildi ve giderlere işlendi.');
  };

  const handlePaymentPersonnelChange = (id: string) => {
    const emp = personnel.find(p => p.id === id);
    setPaymentForm(prev => ({
        ...prev, 
        personnelId: id,
        amount: emp ? emp.monthlySalary : 0
    }));
  };

  const filteredPersonnel = personnel.filter(p => p.fullName.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Personel & Maaş</h1>
          <p className="text-slate-500">Çalışanları yönetin ve maaş ödemelerini takip edin.</p>
        </div>
        <div className="flex gap-2">
           <button
             onClick={() => setActiveTab('EMPLOYEES')}
             className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${activeTab === 'EMPLOYEES' ? 'bg-indigo-600 text-white shadow' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
           >
             Çalışan Listesi
           </button>
           <button
             onClick={() => setActiveTab('PAYROLL')}
             className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${activeTab === 'PAYROLL' ? 'bg-indigo-600 text-white shadow' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
           >
             Maaş Ödemeleri
           </button>
        </div>
      </div>

      {activeTab === 'EMPLOYEES' && (
        <div className="space-y-6 animate-in fade-in duration-300">
           <div className="flex justify-between items-center">
              <div className="relative w-full max-w-xs">
                 <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                    <Search size={20} />
                 </div>
                 <input
                    type="text"
                    placeholder="Personel ara..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
                 />
              </div>
              <button
                onClick={() => handleOpenEmployeeModal()}
                className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium transition-colors shadow-sm"
              >
                <Plus size={20} />
                <span className="hidden sm:inline">Personel Ekle</span>
              </button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredPersonnel.map(p => (
                  <div key={p.id} className={`group bg-white rounded-xl border transition-all duration-200 hover:shadow-md ${p.isActive ? 'border-slate-200' : 'border-slate-100 bg-slate-50 opacity-75'}`}>
                      <div className="p-6">
                          <div className="flex justify-between items-start mb-4">
                             <div className="flex items-center gap-3">
                                 <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white ${p.isActive ? 'bg-slate-800' : 'bg-slate-400'}`}>
                                     {p.fullName.charAt(0)}
                                 </div>
                                 <div>
                                     <h3 className="font-bold text-slate-900">{p.fullName}</h3>
                                     <p className="text-xs text-slate-500">{p.role}</p>
                                 </div>
                             </div>
                             <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${p.isActive ? 'bg-green-50 text-green-700 border-green-200' : 'bg-slate-100 text-slate-500 border-slate-200'}`}>
                                 {p.isActive ? 'Aktif' : 'Ayrıldı'}
                             </span>
                          </div>

                          <div className="space-y-3 border-t border-slate-100 pt-4">
                              <div className="flex justify-between text-sm">
                                  <span className="text-slate-500 flex items-center gap-2"><DollarSign size={14} /> Maaş</span>
                                  <span className="font-bold text-slate-900">{formatCurrency(p.monthlySalary)}</span>
                              </div>
                              <div className="flex justify-between text-sm">
                                  <span className="text-slate-500 flex items-center gap-2"><Calendar size={14} /> Başlangıç</span>
                                  <span className="font-medium text-slate-900">{new Date(p.startDate).toLocaleDateString('tr-TR')}</span>
                              </div>
                          </div>

                          <div className="mt-6">
                              <button 
                                onClick={() => handleOpenEmployeeModal(p)}
                                className="w-full py-2 bg-slate-50 hover:bg-slate-100 text-slate-600 font-medium text-sm rounded-lg transition-colors border border-slate-200"
                              >
                                  Düzenle
                              </button>
                          </div>
                      </div>
                  </div>
              ))}
           </div>
        </div>
      )}

      {activeTab === 'PAYROLL' && (
        <div className="space-y-6 animate-in fade-in duration-300">
           <div className="bg-indigo-50 border border-indigo-100 p-6 rounded-xl flex items-center justify-between">
              <div>
                  <h2 className="text-lg font-bold text-indigo-900 mb-1">Maaş Ödemesi Yap</h2>
                  <p className="text-indigo-600 text-sm">Ödeme yapıldığında otomatik olarak "Giderler" tablosuna işlenir.</p>
              </div>
              <button
                onClick={handleOpenPaymentModal}
                className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-3 rounded-lg font-bold shadow-md transition-transform active:scale-95"
              >
                <Wallet size={20} />
                Ödeme Oluştur
              </button>
           </div>

           <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
             <div className="px-6 py-4 border-b border-slate-200 bg-slate-50/50 flex items-center gap-2">
                <History size={18} className="text-slate-400" />
                <h3 className="font-semibold text-slate-700">Ödeme Geçmişi</h3>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left text-sm">
                 <thead>
                   <tr className="bg-slate-50 border-b border-slate-200">
                     <th className="px-6 py-3 font-semibold text-slate-700">Dönem</th>
                     <th className="px-6 py-3 font-semibold text-slate-700">Personel</th>
                     <th className="px-6 py-3 font-semibold text-slate-700">Ödeme Tarihi</th>
                     <th className="px-6 py-3 font-semibold text-slate-700 text-right">Tutar</th>
                     <th className="px-6 py-3 font-semibold text-slate-700 text-center">Durum</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                    {payments.sort((a,b) => b.date.localeCompare(a.date)).map(pay => {
                        const emp = personnel.find(p => p.id === pay.personnelId);
                        return (
                            <tr key={pay.id} className="hover:bg-slate-50/50">
                                <td className="px-6 py-4 font-mono font-medium text-slate-600">
                                    {pay.period}
                                </td>
                                <td className="px-6 py-4">
                                    <div className="font-medium text-slate-900">{emp?.fullName || 'Bilinmiyor'}</div>
                                    <div className="text-xs text-slate-500">{emp?.role}</div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">
                                    {new Date(pay.date).toLocaleDateString('tr-TR')}
                                </td>
                                <td className="px-6 py-4 text-right font-bold text-slate-900">
                                    {formatCurrency(pay.amount)}
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 border border-green-200 rounded text-xs font-bold uppercase">
                                        <CheckCircle2 size={12} /> Ödendi
                                    </span>
                                </td>
                            </tr>
                        );
                    })}
                    {payments.length === 0 && (
                        <tr>
                            <td colSpan={5} className="px-6 py-12 text-center text-slate-500">
                                Henüz maaş ödemesi yapılmamış.
                            </td>
                        </tr>
                    )}
                 </tbody>
               </table>
             </div>
           </div>
        </div>
      )}

      <Modal
        isOpen={isEmployeeModalOpen}
        onClose={() => setIsEmployeeModalOpen(false)}
        title={editingEmployee ? 'Personel Düzenle' : 'Yeni Personel Ekle'}
      >
        <form onSubmit={handleEmployeeSubmit} className="space-y-4">
            <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700">Ad Soyad</label>
                <div className="relative">
                    <User className="absolute left-3 top-2.5 text-slate-400" size={18} />
                    <input
                        type="text"
                        required
                        value={employeeForm.fullName}
                        onChange={e => setEmployeeForm({...employeeForm, fullName: e.target.value})}
                        className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                    <label className="text-sm font-medium text-slate-700">Görevi</label>
                    <div className="relative">
                        <Briefcase className="absolute left-3 top-2.5 text-slate-400" size={18} />
                        <input
                            type="text"
                            required
                            placeholder="Örn: Ofis Asistanı"
                            value={employeeForm.role}
                            onChange={e => setEmployeeForm({...employeeForm, role: e.target.value})}
                            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                    </div>
                </div>
                <div className="space-y-1.5">
                    <label className="text-sm font-medium text-slate-700">İşe Başlama</label>
                    <input
                        type="date"
                        required
                        value={employeeForm.startDate}
                        onChange={e => setEmployeeForm({...employeeForm, startDate: e.target.value})}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                </div>
            </div>

            <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700">Aylık Maaş (Net)</label>
                <div className="relative">
                    <span className="absolute left-3 top-2.5 text-slate-500 font-bold">₺</span>
                    <input
                        type="number"
                        required
                        min="0"
                        value={employeeForm.monthlySalary}
                        onChange={e => setEmployeeForm({...employeeForm, monthlySalary: Number(e.target.value)})}
                        className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-900"
                    />
                </div>
            </div>

            {editingEmployee && (
                <div className="pt-2">
                    <label className="flex items-center gap-2 cursor-pointer">
                        <input
                            type="checkbox"
                            checked={employeeForm.isActive}
                            onChange={e => setEmployeeForm({...employeeForm, isActive: e.target.checked})}
                            className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500 border-gray-300"
                        />
                        <span className="text-sm text-slate-700">Personel Aktif Çalışıyor</span>
                    </label>
                </div>
            )}

            <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsEmployeeModalOpen(false)} className="flex-1 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200">İptal</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">Kaydet</button>
            </div>
        </form>
      </Modal>

      <Modal
        isOpen={isPaymentModalOpen}
        onClose={() => setIsPaymentModalOpen(false)}
        title="Maaş Ödemesi Oluştur"
      >
        <form onSubmit={handlePaymentSubmit} className="space-y-4">
             <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 flex gap-3 text-amber-800 text-sm mb-4">
                 <AlertCircle size={20} className="shrink-0" />
                 <p>Bu işlem hem maaş geçmişine kayıt atacak hem de <strong>Giderler</strong> modülüne otomatik olarak "Personel Maaş" gideri ekleyecektir.</p>
             </div>

             <div className="space-y-1.5">
                 <label className="text-sm font-medium text-slate-700">Personel Seçimi</label>
                 <select
                    required
                    value={paymentForm.personnelId}
                    onChange={e => handlePaymentPersonnelChange(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none bg-white"
                 >
                     <option value="">Seçiniz...</option>
                     {personnel.filter(p => p.isActive).map(p => (
                         <option key={p.id} value={p.id}>{p.fullName} - {formatCurrency(p.monthlySalary)}</option>
                     ))}
                 </select>
             </div>

             <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1.5">
                     <label className="text-sm font-medium text-slate-700">Ödeme Dönemi</label>
                     <input
                        type="month"
                        required
                        value={paymentForm.period}
                        onChange={e => setPaymentForm({...paymentForm, period: e.target.value})}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                     />
                 </div>
                 <div className="space-y-1.5">
                     <label className="text-sm font-medium text-slate-700">Ödeme Tarihi</label>
                     <input
                        type="date"
                        required
                        value={paymentForm.date}
                        onChange={e => setPaymentForm({...paymentForm, date: e.target.value})}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                     />
                 </div>
             </div>

             <div className="space-y-1.5">
                 <label className="text-sm font-medium text-slate-700">Ödenecek Tutar</label>
                 <div className="relative">
                    <span className="absolute left-3 top-2.5 text-slate-500 font-bold">₺</span>
                    <input
                        type="number"
                        required
                        min="0"
                        value={paymentForm.amount}
                        onChange={e => setPaymentForm({...paymentForm, amount: Number(e.target.value)})}
                        className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-900"
                    />
                 </div>
             </div>

             <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsPaymentModalOpen(false)} className="flex-1 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200">İptal</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-bold">Ödemeyi Tamamla</button>
            </div>
        </form>
      </Modal>
    </div>
  );
};

