import React, { useState, useEffect } from 'react';
import { Expense, ExpenseCategory, Payer, User, SystemLog } from '../types';
import { INITIAL_EXPENSES } from '../constants';
import Modal from '../components/Modal';
import { Plus, Search, Filter, Receipt, Calendar, Tag, UserCircle, Building2, RefreshCw, FileText, PieChart, StickyNote, Trash2, Edit, AlertCircle, CheckCircle, Clock } from 'lucide-react';

interface ExpensesProps {
  currentUser: User;
}

const Expenses: React.FC<ExpensesProps> = ({ currentUser }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterPayer, setFilterPayer] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL'); // ALL, PAID, PENDING
  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    description: '',
    category: ExpenseCategory.OTHER,
    amount: '',
    date: new Date().toISOString().split('T')[0],
    paidBy: Payer.OFFICE,
    notes: '',
    isPaid: true,
  });

  // Load Data
  useEffect(() => {
    const storedExpenses = localStorage.getItem('emlak_expenses');
    if (storedExpenses) {
      setExpenses(JSON.parse(storedExpenses));
    } else {
      // Map initial mock data to have isPaid: true
      const initialWithStatus = INITIAL_EXPENSES.map(e => ({ ...e, isPaid: true }));
      setExpenses(initialWithStatus);
      localStorage.setItem('emlak_expenses', JSON.stringify(initialWithStatus));
    }
  }, []);

  // Save Data
  useEffect(() => {
    if (expenses.length > 0) {
      localStorage.setItem('emlak_expenses', JSON.stringify(expenses));
    }
  }, [expenses]);

  // LOGGING HELPER
  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE', description: string) => {
    try {
        const newLog: SystemLog = {
          id: Date.now().toString(),
          date: new Date().toISOString(),
          user: currentUser.name,
          action: action,
          module: 'EXPENSE',
          description: description
        };
        const storedLogs = localStorage.getItem('emlak_logs');
        let existingLogs = storedLogs ? JSON.parse(storedLogs) : [];
        localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...existingLogs]));
    } catch (error) {
        console.error("Logging failed:", error);
    }
  };

  const handleOpenModal = (expenseToEdit?: Expense) => {
    if (expenseToEdit) {
      setEditingId(expenseToEdit.id);
      setFormData({
        description: expenseToEdit.description,
        category: expenseToEdit.category,
        amount: expenseToEdit.amount.toString(),
        date: expenseToEdit.date,
        paidBy: expenseToEdit.paidBy,
        notes: expenseToEdit.notes || '',
        isPaid: expenseToEdit.isPaid,
      });
    } else {
      setEditingId(null);
      setFormData({
        description: '',
        category: ExpenseCategory.OTHER,
        amount: '',
        date: new Date().toISOString().split('T')[0],
        paidBy: Payer.OFFICE,
        notes: '',
        isPaid: true,
      });
    }
    setIsModalOpen(true);
  };

  const handleRowClick = (expense: Expense) => {
    setSelectedExpense(expense);
    setIsViewModalOpen(true);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Bu gider kaydını silmek istediğinize emin misiniz?')) {
      const exp = expenses.find(e => e.id === id);
      if (exp) logAction('DELETE', `Gider Silindi: ${exp.description} (${exp.amount} TL)`);
      setExpenses(prev => prev.filter(e => e.id !== id));
      setIsViewModalOpen(false);
      setSelectedExpense(null);
    }
  };

  const handleMarkAsPaid = (id: string) => {
    setExpenses(prev => prev.map(e => e.id === id ? { ...e, isPaid: true } : e));
    const exp = expenses.find(e => e.id === id);
    if (exp) logAction('APPROVE', `Gider Ödemesi Yapıldı: ${exp.description}`);
    setIsViewModalOpen(false);
    setSelectedExpense(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setExpenses(prev => prev.map(exp => 
        exp.id === editingId ? {
          ...exp,
          description: formData.description,
          category: formData.category,
          amount: Number(formData.amount),
          date: formData.date,
          paidBy: formData.paidBy,
          notes: formData.notes,
          isPaid: formData.isPaid,
        } : exp
      ));
      logAction('UPDATE', `Gider Düzenlendi: ${formData.description}`);
    } else {
      const newExpense: Expense = {
        id: Date.now().toString(),
        description: formData.description,
        category: formData.category,
        amount: Number(formData.amount),
        date: formData.date,
        paidBy: formData.paidBy,
        notes: formData.notes,
        isPaid: formData.isPaid,
      };
      setExpenses(prev => [newExpense, ...prev]);
      logAction('CREATE', `Yeni Gider: ${formData.description} (${formData.isPaid ? 'Ödendi' : 'Borç'})`);
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleClearFilters = () => {
    setSearchTerm('');
    setFilterCategory('ALL');
    setFilterPayer('ALL');
    setFilterStatus('ALL');
    setFilterDateStart('');
    setFilterDateEnd('');
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const getCategoryLabel = (cat: string) => {
    const labels: any = {
      [ExpenseCategory.RENT]: 'Kira',
      [ExpenseCategory.OFFICE_SUPPLIES]: 'Ofis Malzemeleri',
      [ExpenseCategory.MARKETING]: 'Pazarlama/İlan',
      [ExpenseCategory.UTILITIES]: 'Faturalar',
      [ExpenseCategory.FOOD]: 'Yemek/Temsil',
      [ExpenseCategory.PERSONNEL]: 'Personel Maaş',
      [ExpenseCategory.OTHER]: 'Diğer',
    };
    return labels[cat] || cat;
  };

  const getCategoryStyle = (cat: ExpenseCategory) => {
    const styles: Record<ExpenseCategory, string> = {
      [ExpenseCategory.RENT]: 'bg-indigo-50 text-indigo-700 border-indigo-200',
      [ExpenseCategory.UTILITIES]: 'bg-yellow-50 text-yellow-700 border-yellow-200',
      [ExpenseCategory.OFFICE_SUPPLIES]: 'bg-stone-50 text-stone-700 border-stone-200',
      [ExpenseCategory.MARKETING]: 'bg-pink-50 text-pink-700 border-pink-200',
      [ExpenseCategory.FOOD]: 'bg-emerald-50 text-emerald-700 border-emerald-200',
      [ExpenseCategory.PERSONNEL]: 'bg-orange-50 text-orange-700 border-orange-200',
      [ExpenseCategory.OTHER]: 'bg-slate-50 text-slate-600 border-slate-200',
    };
    return styles[cat] || styles[ExpenseCategory.OTHER];
  };

  // --- FILTER LOGIC ---
  const filteredExpenses = expenses.filter(e => {
    const matchesSearch = e.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || e.category === filterCategory;
    const matchesPayer = filterPayer === 'ALL' || e.paidBy === filterPayer;
    const matchesStatus = filterStatus === 'ALL' || (filterStatus === 'PAID' ? e.isPaid : !e.isPaid);

    let matchesDate = true;
    if (filterDateStart) matchesDate = matchesDate && e.date >= filterDateStart;
    if (filterDateEnd) matchesDate = matchesDate && e.date <= filterDateEnd;

    return matchesSearch && matchesCategory && matchesPayer && matchesStatus && matchesDate;
  });

  const totalExpenses = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
  const totalPaid = filteredExpenses.filter(e => e.isPaid).reduce((acc, curr) => acc + curr.amount, 0);
  const totalDebt = filteredExpenses.filter(e => !e.isPaid).reduce((acc, curr) => acc + curr.amount, 0);

  const hasActiveFilters = filterCategory !== 'ALL' || filterPayer !== 'ALL' || filterStatus !== 'ALL' || filterDateStart !== '' || filterDateEnd !== '';

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Gider Yönetimi</h1>
          <p className="text-slate-500">Ofis harcamalarını ve borçları takip edin.</p>
        </div>
        <button
          onClick={() => handleOpenModal()}
          className="flex items-center justify-center gap-2 bg-rose-600 hover:bg-rose-700 text-white px-4 py-2.5 rounded-lg font-medium transition-colors shadow-sm"
        >
          <Plus size={20} />
          <span>Yeni Gider Ekle</span>
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
                <p className="text-xs font-bold text-slate-400 uppercase mb-1">Toplam Gider</p>
                <p className="text-2xl font-black text-slate-900">{formatCurrency(totalExpenses)}</p>
            </div>
            <div className="p-3 bg-slate-50 text-slate-400 rounded-xl">
                <Receipt size={24} />
            </div>
        </div>

        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
                <p className="text-xs font-bold text-emerald-600 uppercase mb-1">Gerçekleşen Ödeme</p>
                <p className="text-2xl font-black text-emerald-700">{formatCurrency(totalPaid)}</p>
            </div>
            <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl">
                <CheckCircle size={24} />
            </div>
        </div>

        <div className="bg-white p-6 rounded-xl border border-orange-200 shadow-sm flex items-center justify-between relative overflow-hidden group">
            {totalDebt > 0 && (
                <div className="absolute top-0 right-0 p-1 bg-orange-500 text-white text-[8px] font-bold px-2 rounded-bl">DİKKAT</div>
            )}
            <div>
                <p className="text-xs font-bold text-orange-600 uppercase mb-1">Toplam Borç (Bekleyen)</p>
                <p className="text-2xl font-black text-orange-700">{formatCurrency(totalDebt)}</p>
            </div>
            <div className="p-3 bg-orange-50 text-orange-600 rounded-xl">
                <Clock size={24} />
            </div>
        </div>
      </div>

      {/* Search and Filter */}
      <div className="space-y-4">
        <div className="flex gap-4">
          <div className="relative flex-1">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
              <Search size={20} />
            </div>
            <input
              type="text"
              placeholder="Açıklama veya kategori ara..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-rose-500 outline-none transition-shadow"
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`px-4 py-2 border rounded-xl flex items-center gap-2 transition-colors ${showFilters || hasActiveFilters ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
          >
            <Filter size={20} />
            <span className="hidden sm:inline">Filtrele</span>
          </button>
        </div>

        {showFilters && (
          <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-5 gap-4 items-end animate-in slide-in-from-top-2">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-500">Kategori</label>
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm">
                  <option value="ALL">Tümü</option>
                  {Object.values(ExpenseCategory).map(cat => (
                    <option key={cat} value={cat}>{getCategoryLabel(cat)}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-500">Durum</label>
                <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm">
                  <option value="ALL">Tümü</option>
                  <option value="PAID">Ödendi</option>
                  <option value="PENDING">Ödeme Bekliyor</option>
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-500">Başlangıç</label>
                <input type="date" value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-500">Bitiş</label>
                <input type="date" value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" />
              </div>
              <button onClick={handleClearFilters} className="px-3 py-2 bg-slate-100 text-slate-600 rounded-lg text-xs font-bold hover:bg-slate-200 flex items-center justify-center gap-2">
                <RefreshCw size={14} /> Temizle
              </button>
          </div>
        )}
      </div>

      {/* Expenses Table */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 font-semibold text-slate-700">Tarih</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Açıklama</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Kategori</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Durum</th>
                <th className="px-6 py-4 font-semibold text-rose-700 text-right">Tutar</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredExpenses.map((expense) => (
                <tr key={expense.id} onClick={() => handleRowClick(expense)} className="hover:bg-slate-50/50 transition-colors cursor-pointer group">
                  <td className="px-6 py-4 text-slate-500 whitespace-nowrap font-mono">{new Date(expense.date).toLocaleDateString('tr-TR')}</td>
                  <td className="px-6 py-4 font-medium text-slate-900">{expense.description}</td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${getCategoryStyle(expense.category)}`}>
                        {getCategoryLabel(expense.category)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    {expense.isPaid ? (
                        <span className="inline-flex items-center gap-1 text-emerald-600 font-bold text-xs">
                            <CheckCircle size={14} /> Ödendi
                        </span>
                    ) : (
                        <span className="inline-flex items-center gap-1 text-orange-600 font-bold text-xs animate-pulse">
                            <AlertCircle size={14} /> Borç (Bekliyor)
                        </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right font-black text-rose-600">
                    -{formatCurrency(expense.amount)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Expense Modal */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Gider Düzenle' : 'Yeni Gider Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Açıklama</label>
            <input required type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-rose-500" placeholder="Hizmet/Ürün açıklaması" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Kategori</label>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as ExpenseCategory})} className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white outline-none">
                {Object.values(ExpenseCategory).map(cat => <option key={cat} value={cat}>{getCategoryLabel(cat)}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Harcama Tarihi</label>
              <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Tutar</label>
            <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-500 font-bold">₺</span>
                <input required type="number" min="0" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg font-bold text-slate-900 outline-none focus:ring-2 focus:ring-rose-500" placeholder="0.00" />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Ödeme Durumu</label>
            <div className="grid grid-cols-2 gap-2">
                <button type="button" onClick={() => setFormData({...formData, isPaid: true})} className={`py-2 rounded-lg border text-sm font-bold transition-all ${formData.isPaid ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-slate-500 border-slate-200'}`}>Ödendi</button>
                <button type="button" onClick={() => setFormData({...formData, isPaid: false})} className={`py-2 rounded-lg border text-sm font-bold transition-all ${!formData.isPaid ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-slate-500 border-slate-200'}`}>Ödeme Bekliyor</button>
            </div>
          </div>

          {!formData.isPaid && (
              <p className="text-xs text-orange-600 bg-orange-50 p-2 rounded flex items-start gap-2">
                  <AlertCircle size={14} className="shrink-0 mt-0.5" />
                  Bu gider "Borç" olarak kaydedilecektir. Ödeme yapıldığında "Ödendi" olarak güncellenebilir.
              </p>
          )}

          <div className="pt-4 flex gap-3">
            <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg font-medium">İptal</button>
            <button type="submit" className="flex-1 px-4 py-2 bg-rose-600 text-white rounded-lg font-bold">Kaydet</button>
          </div>
        </form>
      </Modal>

      {/* Detail Modal */}
      <Modal isOpen={isViewModalOpen} onClose={() => setIsViewModalOpen(false)} title="Gider Detayı">
        {selectedExpense && (
          <div className="space-y-6">
            <div className="text-center py-4 bg-slate-50 rounded-xl border border-slate-100">
                <p className="text-xs font-bold text-slate-400 uppercase">Hizmet Bedeli</p>
                <h2 className="text-3xl font-black text-slate-900">{formatCurrency(selectedExpense.amount)}</h2>
                <div className="mt-2">
                    {selectedExpense.isPaid ? (
                        <span className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-full text-xs font-black uppercase border border-emerald-200">ÖDENDİ</span>
                    ) : (
                        <span className="px-3 py-1 bg-orange-100 text-orange-700 rounded-full text-xs font-black uppercase border border-orange-200">ÖDEME BEKLİYOR</span>
                    )}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="p-3 bg-white border border-slate-100 rounded-lg">
                    <p className="text-slate-500 mb-1 font-semibold uppercase text-[10px]">Tarih</p>
                    <p className="font-bold text-slate-800">{new Date(selectedExpense.date).toLocaleDateString('tr-TR')}</p>
                </div>
                <div className="p-3 bg-white border border-slate-100 rounded-lg">
                    <p className="text-slate-500 mb-1 font-semibold uppercase text-[10px]">Kategori</p>
                    <p className="font-bold text-slate-800">{getCategoryLabel(selectedExpense.category)}</p>
                </div>
            </div>

            <div className="p-4 bg-white border border-slate-100 rounded-lg">
                <p className="text-slate-500 mb-1 font-semibold uppercase text-[10px]">Açıklama</p>
                <p className="text-slate-800 font-medium">{selectedExpense.description}</p>
            </div>

            {selectedExpense.notes && (
                <div className="p-4 bg-amber-50 border border-amber-100 rounded-lg text-sm text-amber-900 italic">
                    <StickyNote size={14} className="mb-2" />
                    {selectedExpense.notes}
                </div>
            )}

            <div className="pt-4 flex gap-3 flex-wrap sm:flex-nowrap">
                {!selectedExpense.isPaid && (
                    <button onClick={() => handleMarkAsPaid(selectedExpense.id)} className="w-full flex-1 py-3 bg-emerald-600 text-white font-bold rounded-lg hover:bg-emerald-700 flex items-center justify-center gap-2">
                        <CheckCircle size={18} /> Ödeme Yapıldı
                    </button>
                )}
                <button onClick={() => { setIsViewModalOpen(false); handleOpenModal(selectedExpense); }} className="w-full flex-1 py-3 bg-indigo-50 text-indigo-700 font-bold rounded-lg hover:bg-indigo-100 flex items-center justify-center gap-2 border border-indigo-100">
                    <Edit size={18} /> Düzenle
                </button>
                <button onClick={() => handleDelete(selectedExpense.id)} className="w-full flex-1 py-3 bg-red-50 text-red-700 font-bold rounded-lg hover:bg-red-100 flex items-center justify-center gap-2 border border-red-100">
                    <Trash2 size={18} /> Sil
                </button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default Expenses;

import React, { useEffect, useState, useMemo } from 'react';
import { User, Consultant, Transaction, Expense } from '../types';
import { INITIAL_CONSULTANTS, INITIAL_TRANSACTIONS, INITIAL_EXPENSES } from '../constants';
import { ShieldCheck, Users, Banknote, CheckCircle2, TrendingUp, Building2, Receipt, Target, AlertTriangle } from 'lucide-react';

interface DashboardProps {
  user: User;
}

const Dashboard: React.FC<DashboardProps> = ({ user }) => {
  const [activeConsultantCount, setActiveConsultantCount] = useState<number>(0);
  const [totalRevenue, setTotalRevenue] = useState<number>(0);
  const [officeRevenue, setOfficeRevenue] = useState<number>(0);
  const [totalExpenses, setTotalExpenses] = useState<number>(0);
  const [unpaidDebts, setUnpaidDebts] = useState<number>(0);

  // Goal State
  const [monthlyGoal] = useState<number>(100000);

  const stats = useMemo(() => {
    const storedConsultants = localStorage.getItem('emlak_consultants');
    const consultants: Consultant[] = storedConsultants ? JSON.parse(storedConsultants) : INITIAL_CONSULTANTS;

    const storedTransactions = localStorage.getItem('emlak_transactions');
    const transactions: Transaction[] = storedTransactions ? JSON.parse(storedTransactions) : INITIAL_TRANSACTIONS;

    const storedExpenses = localStorage.getItem('emlak_expenses');
    const expenses: Expense[] = storedExpenses ? JSON.parse(storedExpenses) : INITIAL_EXPENSES;

    const totalRev = transactions.reduce((acc, t) => acc + t.totalRevenue, 0);
    const officeRev = transactions.reduce((acc, t) => acc + t.officeRevenue, 0);
    const totalExp = expenses.reduce((acc, e) => acc + e.amount, 0);
    const totalUnpaid = expenses.filter(e => !e.isPaid).reduce((acc, e) => acc + e.amount, 0);

    return {
      activeConsultants: consultants.filter(c => c.isActive).length,
      totalRevenue: totalRev,
      officeRevenue: officeRev,
      totalExpenses: totalExp,
      unpaidDebts: totalUnpaid,
      netProfit: officeRev - totalExp,
    };
  }, []);

  useEffect(() => {
    setActiveConsultantCount(stats.activeConsultants);
    setTotalRevenue(stats.totalRevenue);
    setOfficeRevenue(stats.officeRevenue);
    setTotalExpenses(stats.totalExpenses);
    setUnpaidDebts(stats.unpaidDebts);
  }, [stats]);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const goalProgress = Math.min((stats.totalRevenue / monthlyGoal) * 100, 100);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Hoş Geldiniz, {user.name}</h1>
          <p className="text-slate-500">Ofisinizin güncel finansal durumuna göz atın.</p>
        </div>
        <div className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-700 rounded-full text-sm font-medium border border-indigo-100">
          <ShieldCheck size={16} />
          Yetki: {user.role}
        </div>
      </div>

      {/* Debt Warning Alert */}
      {unpaidDebts > 0 && (
          <div className="bg-orange-50 border border-orange-200 p-4 rounded-xl flex items-center justify-between animate-pulse">
              <div className="flex items-center gap-3">
                <AlertTriangle className="text-orange-600" size={24} />
                <div>
                    <h3 className="font-bold text-orange-900 text-sm">Bekleyen Ödemeleriniz Var!</h3>
                    <p className="text-orange-700 text-xs">Toplam <strong>{formatCurrency(unpaidDebts)}</strong> tutarında ödenmemiş gider kaydı mevcut.</p>
                </div>
              </div>
              <button onClick={() => window.location.hash = '/expenses'} className="text-xs font-bold text-orange-600 bg-white px-3 py-1.5 rounded-lg border border-orange-200 hover:bg-orange-100 transition-colors">Giderlere Git</button>
          </div>
      )}

      {/* Main Stats Row */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                <Banknote size={64} className="text-emerald-600" />
            </div>
            <p className="text-sm font-medium text-slate-500">Toplam Ciro</p>
            <p className="text-3xl font-bold text-slate-900 mt-1">{formatCurrency(totalRevenue)}</p>
            <div className="mt-4 flex items-center gap-1 text-xs font-bold text-emerald-600">
                <TrendingUp size={14} />
                <span>Brüt Hacim</span>
            </div>
        </div>

        <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 shadow-xl relative overflow-hidden text-white">
            <div className="absolute top-0 right-0 p-4 opacity-10">
                <Building2 size={64} className="text-white" />
            </div>
            <p className="text-sm font-medium text-slate-400">Ofis Geliri (Brüt)</p>
            <p className="text-3xl font-bold text-white mt-1">{formatCurrency(officeRevenue)}</p>
            <div className="mt-4 flex items-center gap-1 text-xs font-bold text-indigo-400 uppercase">
                Pay: %{Math.round((stats.officeRevenue / (stats.totalRevenue || 1)) * 100)}
            </div>
        </div>

        <div className="bg-emerald-600 p-6 rounded-2xl shadow-lg shadow-emerald-900/10 text-white relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-20">
                <CheckCircle2 size={64} className="text-white" />
            </div>
            <p className="text-sm font-medium text-emerald-100">Net Kâr</p>
            <p className="text-3xl font-bold text-white mt-1">{formatCurrency(stats.netProfit)}</p>
            <p className="text-xs text-emerald-100 mt-4 italic">Giderler sonrası kalan tutar</p>
        </div>
      </div>

      {/* Goal Tracker */}
      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-3">
                  <div className="p-3 bg-rose-50 text-rose-500 rounded-xl">
                    <Target size={28} />
                  </div>
                  <div>
                    <h3 className="font-bold text-xl text-slate-800">Aylık Performans Hedefi</h3>
                    <p className="text-sm text-slate-500">Bu ayki ciro hedefine olan ilerlemeniz</p>
                  </div>
              </div>
              <div className="text-right">
                <p className="text-xs text-slate-400 uppercase font-bold mb-1">Hedef</p>
                <p className="text-lg font-bold text-slate-700 bg-slate-100 px-4 py-1.5 rounded-lg border border-slate-200">
                    {formatCurrency(monthlyGoal)}
                </p>
              </div>
          </div>

          <div className="space-y-6">
              <div className="flex justify-between items-end">
                  <span className="text-sm font-bold text-slate-600 uppercase tracking-wider">Mevcut Durum</span>
                  <span className={`text-2xl font-black ${goalProgress >= 100 ? "text-emerald-600" : "text-indigo-600"}`}>
                      %{Math.round(goalProgress)}
                  </span>
              </div>
              <div className="w-full bg-slate-100 h-6 rounded-full overflow-hidden border border-slate-200 p-1">
                  <div 
                      className={`h-full rounded-full transition-all duration-1000 ease-out shadow-sm relative ${goalProgress >= 100 ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-indigo-600'}`} 
                      style={{ width: `${goalProgress}%` }}
                  >
                    {goalProgress > 10 && (
                        <div className="absolute inset-0 bg-white/20 animate-pulse"></div>
                    )}
                  </div>
              </div>
              <div className="flex justify-between items-center bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <p className="text-sm text-slate-600">
                    Kalan İhtiyaç: <span className="font-bold text-slate-900">{formatCurrency(Math.max(0, monthlyGoal - totalRevenue))}</span>
                  </p>
                  {goalProgress >= 100 && (
                      <span className="flex items-center gap-2 text-sm font-bold text-emerald-600">
                          <CheckCircle2 size={18} /> Tebrikler, Aylık Hedef Yakalandı!
                      </span>
                  )}
              </div>
          </div>
      </div>

      {/* Secondary Info Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
         <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-rose-50 text-rose-600 rounded-xl">
                    <Receipt size={24} />
                </div>
                <div>
                    <h4 className="font-bold text-slate-800">Toplam Giderler</h4>
                    <p className="text-2xl font-bold text-rose-600">{formatCurrency(stats.totalExpenses)}</p>
                </div>
            </div>
            <div className="text-right">
                <p className="text-[10px] text-slate-400 uppercase font-bold">Gider Oranı</p>
                <p className="text-sm font-bold text-slate-600">%{Math.round((stats.totalExpenses / (stats.officeRevenue || 1)) * 100)}</p>
            </div>
         </div>

         <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl">
                    <Users size={24} />
                </div>
                <div>
                    <h4 className="font-bold text-slate-800">Aktif Kadro</h4>
                    <p className="text-2xl font-bold text-slate-900">{stats.activeConsultants} Danışman</p>
                </div>
            </div>
            <div className="bg-indigo-50 px-3 py-1 rounded-full border border-indigo-100">
                <span className="text-xs font-bold text-indigo-600">Ekip Aktif</span>
            </div>
         </div>
      </div>
    </div>
  );
};

export default Dashboard;

