}

export interface User {
  id: string;
  username: string;
  name: string;
  role: UserRole;
}

// --- DANIŞMAN ŞEMASI ---
export interface Consultant {
  id: string;
  fullName: string;
  phoneNumber: string;
  commissionRate: number; 
  startDate: string; 
  isActive: boolean;
}

// --- TEDARİKÇİ / FİRMA ŞEMASI (Cari Takip) ---
