export enum TransactionType {
  SALE = 'SATIS',
  RENT = 'KIRALAMA',
}

export enum PaymentStatus {
  PENDING = 'BEKLIYOR',
  PAID = 'ODENDI',
}

export interface Transaction {
  id: string;
  propertyName: string;
  type: TransactionType;
  customerName: string;
  consultantId: string;
  date: string;
  totalRevenue: number;
  officeRevenue: number;
