import React, { useState, useEffect, useMemo } from 'react';
import { Vendor, Expense, User, SystemLog, ExpenseCategory } from '../types';
import { INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Building, Plus, Search, Phone, Mail, FileText, Wallet, ArrowRight, User as UserIcon, AlertCircle } from 'lucide-react';

interface VendorsProps {
  currentUser: User;
}

const Vendors: React.FC<VendorsProps> = ({ currentUser }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Vendor>>({
    name: '',
    contactPerson: '',
    phone: '',
    email: '',
    taxNumber: '',
    taxOffice: '',
    category: ExpenseCategory.OTHER,
  });

  useEffect(() => {
    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);

    const storedExpenses = localStorage.getItem('emlak_expenses');
    setExpenses(storedExpenses ? JSON.parse(storedExpenses) : []);
  }, []);

  useEffect(() => {
    if (vendors.length > 0) localStorage.setItem('emlak_vendors', JSON.stringify(vendors));
  }, [vendors]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'VENDOR',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const getVendorBalance = (vendorId: string) => {
    return expenses
      .filter(e => e.vendorId === vendorId && !e.isPaid)
      .reduce((acc, curr) => acc + curr.amount, 0);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const handleOpenModal = (vendor?: Vendor) => {
    if (vendor) {
      setEditingId(vendor.id);
      setFormData({ ...vendor });
    } else {
      setEditingId(null);
      setFormData({ name: '', contactPerson: '', phone: '', email: '', category: ExpenseCategory.OTHER });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setVendors(prev => prev.map(v => v.id === editingId ? { ...v, ...formData } as Vendor : v));
      logAction('UPDATE', `Firma Bilgisi Güncellendi: ${formData.name}`);
    } else {
      const newVendor: Vendor = { id: Date.now().toString(), ...formData as Omit<Vendor, 'id'> };
      setVendors(prev => [...prev, newVendor]);
      logAction('CREATE', `Yeni Firma/Tedarikçi Eklendi: ${newVendor.name}`);
    }
    setIsModalOpen(false);
  };

  const filteredVendors = vendors.filter(v => v.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Firmalar & Cariler</h1>
          <p className="text-slate-500">Hizmet alınan tedarikçileri ve borç bakiyelerini yönetin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Firma Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-3 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Firma adı ile ara..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVendors.map(vendor => {
          const balance = getVendorBalance(vendor.id);
          return (
            <div key={vendor.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow overflow-hidden group">
              <div className="p-6">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-3 bg-slate-50 rounded-xl text-slate-600 group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors">
                    <Building size={24} />
                  </div>
                  {balance > 0 && (
                    <span className="flex items-center gap-1 text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-1 rounded-full border border-orange-100">
                      <AlertCircle size={12} /> BORÇ VAR
                    </span>
                  )}
                </div>

                <h3 className="text-lg font-bold text-slate-900 truncate mb-1">{vendor.name}</h3>
                <p className="text-xs text-slate-500 flex items-center gap-1 mb-4">
                  <UserIcon size={12} /> {vendor.contactPerson || 'Yetkili belirtilmedi'}
                </p>

                <div className="space-y-2 mb-6">
                  <div className="flex items-center gap-2 text-sm text-slate-600">
                    <Phone size={14} className="text-slate-400" />
                    <span>{vendor.phone}</span>
                  </div>
                  {vendor.email && (
                    <div className="flex items-center gap-2 text-sm text-slate-600">
                      <Mail size={14} className="text-slate-400" />
                      <span>{vendor.email}</span>
                    </div>
                  )}
                </div>

                <div className="pt-4 border-t border-slate-100 flex items-center justify-between">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Açık Hesap</p>
                    <p className={`text-xl font-black ${balance > 0 ? 'text-orange-600' : 'text-slate-400'}`}>
                      {formatCurrency(balance)}
                    </p>
                  </div>
                  <button onClick={() => handleOpenModal(vendor)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors">
                    <FileText size={20} />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Firma Düzenle' : 'Yeni Firma Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Firma Adı</label>
            <input required type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Yetkili Kişi</label>
              <input type="text" value={formData.contactPerson} onChange={e => setFormData({...formData, contactPerson: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Telefon</label>
              <input required type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">E-Posta</label>
            <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Vergi No</label>
              <input type="text" value={formData.taxNumber} onChange={e => setFormData({...formData, taxNumber: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Vergi Dairesi</label>
              <input type="text" value={formData.taxOffice} onChange={e => setFormData({...formData, taxOffice: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>
          <div className="pt-4 flex gap-3">
            <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg font-medium">İptal</button>
            <button type="submit" className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold">Kaydet</button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Vendors;

import React, { useState, useEffect } from 'react';
import { Expense, ExpenseCategory, Payer, User, SystemLog, Vendor } from '../types';
import { INITIAL_EXPENSES, INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Plus, Search, Filter, Receipt, Calendar, Tag, UserCircle, Building2, RefreshCw, FileText, PieChart, StickyNote, Trash2, Edit, AlertCircle, CheckCircle, Clock, Building } from 'lucide-react';

interface ExpensesProps {
  currentUser: User;
}

const Expenses: React.FC<ExpensesProps> = ({ currentUser }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL'); 
  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    description: '',
    category: ExpenseCategory.OTHER,
    amount: '',
    date: new Date().toISOString().split('T')[0],
    paidBy: Payer.OFFICE,
    notes: '',
    isPaid: true,
    vendorId: '', // Yeni: Firma seçimi için
  });

  // Load Data
  useEffect(() => {
    const storedExpenses = localStorage.getItem('emlak_expenses');
    if (storedExpenses) {
      setExpenses(JSON.parse(storedExpenses));
    } else {
      const initialWithStatus = INITIAL_EXPENSES.map(e => ({ ...e, isPaid: true }));
      setExpenses(initialWithStatus);
      localStorage.setItem('emlak_expenses', JSON.stringify(initialWithStatus));
    }

    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);
  }, []);

  // Save Data
  useEffect(() => {
    if (expenses.length > 0) {
      localStorage.setItem('emlak_expenses', JSON.stringify(expenses));
    }
  }, [expenses]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'EXPENSE',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const handleOpenModal = (expenseToEdit?: Expense) => {
    if (expenseToEdit) {
      setEditingId(expenseToEdit.id);
      setFormData({
        description: expenseToEdit.description,
        category: expenseToEdit.category,
        amount: expenseToEdit.amount.toString(),
        date: expenseToEdit.date,
        paidBy: expenseToEdit.paidBy,
        notes: expenseToEdit.notes || '',
        isPaid: expenseToEdit.isPaid,
        vendorId: expenseToEdit.vendorId || '',
      });
    } else {
      setEditingId(null);
      setFormData({
        description: '',
        category: ExpenseCategory.OTHER,
        amount: '',
        date: new Date().toISOString().split('T')[0],
        paidBy: Payer.OFFICE,
        notes: '',
        isPaid: true,
        vendorId: '',
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setExpenses(prev => prev.map(exp => 
        exp.id === editingId ? {
          ...exp,
          description: formData.description,
          category: formData.category,
          amount: Number(formData.amount),
          date: formData.date,
          paidBy: formData.paidBy,
          notes: formData.notes,
          isPaid: formData.isPaid,
          vendorId: formData.vendorId || undefined,
        } : exp
      ));
      logAction('UPDATE', `Gider Düzenlendi: ${formData.description}`);
    } else {
      const newExpense: Expense = {
        id: Date.now().toString(),
        description: formData.description,
        category: formData.category,
        amount: Number(formData.amount),
        date: formData.date,
        paidBy: formData.paidBy,
        notes: formData.notes,
        isPaid: formData.isPaid,
        vendorId: formData.vendorId || undefined,
      };
      setExpenses(prev => [newExpense, ...prev]);
      logAction('CREATE', `Yeni Gider: ${formData.description}`);
    }
    setIsModalOpen(false);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const getVendorName = (vendorId?: string) => {
    if (!vendorId) return '-';
    return vendors.find(v => v.id === vendorId)?.name || 'Bilinmeyen Firma';
  };

  const getCategoryLabel = (cat: string) => {
    const labels: any = {
      [ExpenseCategory.RENT]: 'Kira',
      [ExpenseCategory.OFFICE_SUPPLIES]: 'Ofis Malzemeleri',
      [ExpenseCategory.MARKETING]: 'Pazarlama/İlan',
      [ExpenseCategory.UTILITIES]: 'Faturalar',
      [ExpenseCategory.FOOD]: 'Yemek/Temsil',
      [ExpenseCategory.PERSONNEL]: 'Personel Maaş',
      [ExpenseCategory.OTHER]: 'Diğer',
    };
    return labels[cat] || cat;
  };

  const filteredExpenses = expenses.filter(e => {
    const matchesSearch = e.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || e.category === filterCategory;
    const matchesStatus = filterStatus === 'ALL' || (filterStatus === 'PAID' ? e.isPaid : !e.isPaid);
    return matchesSearch && matchesCategory && matchesStatus;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Gider Yönetimi</h1>
          <p className="text-slate-500">Ofis harcamalarını ve cari borçları takip edin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-rose-600 hover:bg-rose-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Yeni Gider Ekle</span>
        </button>
      </div>

      <div className="flex gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-3 text-slate-400" size={20} />
          <input type="text" placeholder="Giderlerde ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-rose-500 shadow-sm" />
        </div>
        <button onClick={() => setShowFilters(!showFilters)} className={`px-4 py-2 border rounded-xl flex items-center gap-2 transition-colors ${showFilters ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-200 text-slate-600'}`}>
          <Filter size={20} />
          <span className="hidden sm:inline">Filtrele</span>
        </button>
      </div>

      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 font-semibold text-slate-700">Tarih</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Firma / Cari</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Açıklama</th>
                <th className="px-6 py-4 font-semibold text-slate-700 text-right">Tutar</th>
                <th className="px-6 py-4 font-semibold text-slate-700 text-center">Durum</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredExpenses.map((expense) => (
                <tr key={expense.id} onClick={() => { setSelectedExpense(expense); setIsViewModalOpen(true); }} className="hover:bg-slate-50/50 transition-colors cursor-pointer">
                  <td className="px-6 py-4 text-slate-500">{new Date(expense.date).toLocaleDateString('tr-TR')}</td>
                  <td className="px-6 py-4 font-bold text-slate-800">{getVendorName(expense.vendorId)}</td>
                  <td className="px-6 py-4 text-slate-600">{expense.description}</td>
                  <td className="px-6 py-4 text-right font-black text-rose-600">-{formatCurrency(expense.amount)}</td>
                  <td className="px-6 py-4 text-center">
                    {expense.isPaid ? (
                        <span className="inline-flex items-center gap-1 text-emerald-600 font-bold text-[10px] uppercase"><CheckCircle size={14} /> Ödendi</span>
                    ) : (
                        <span className="inline-flex items-center gap-1 text-orange-600 font-bold text-[10px] uppercase"><Clock size={14} /> Bekliyor</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Gider Düzenle' : 'Yeni Gider Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Firma / Cari Seçimi (Opsiyonel)</label>
            <select value={formData.vendorId} onChange={e => setFormData({...formData, vendorId: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none bg-white">
              <option value="">Firma Seçilmedi (Genel Gider)</option>
              {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Açıklama</label>
            <input required type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Kategori</label>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as ExpenseCategory})} className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white">
                {Object.values(ExpenseCategory).map(cat => <option key={cat} value={cat}>{getCategoryLabel(cat)}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Tarih</label>
              <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Tutar</label>
            <input required type="number" min="0" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none font-bold" />
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Ödeme Durumu</label>
            <div className="grid grid-cols-2 gap-2">
                <button type="button" onClick={() => setFormData({...formData, isPaid: true})} className={`py-2 rounded-lg border text-sm font-bold ${formData.isPaid ? 'bg-emerald-600 text-white' : 'bg-white text-slate-500'}`}>Ödendi</button>
                <button type="button" onClick={() => setFormData({...formData, isPaid: false})} className={`py-2 rounded-lg border text-sm font-bold ${!formData.isPaid ? 'bg-orange-600 text-white' : 'bg-white text-slate-500'}`}>Borç Kaydet</button>
            </div>
          </div>
          <button type="submit" className="w-full px-4 py-3 bg-rose-600 text-white rounded-lg font-bold mt-4 shadow-lg active:scale-95 transition-transform">Gideri Kaydet</button>
        </form>
      </Modal>
    </div>
  );
};

export default Expenses;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Consultants from './pages/Consultants';
import Transactions from './pages/Transactions';
import Expenses from './pages/Expenses';
import PersonnelPage from './pages/Personnel';
import Vendors from './pages/Vendors'; // Yeni sayfa eklendi
import Reports from './pages/Reports';
import Settings from './pages/Settings';
import { User } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('/');

  useEffect(() => {
    const storedUser = localStorage.getItem('emlak_user');
    if (storedUser) {
      try { setUser(JSON.parse(storedUser)); } catch (e) { localStorage.removeItem('emlak_user'); }
    }
  }, []);

  const handleLogin = (newUser: User) => {
    setUser(newUser);
    localStorage.setItem('emlak_user', JSON.stringify(newUser));
    setCurrentPage('/');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('emlak_user');
    setCurrentPage('/');
  };

  const renderPage = () => {
    if (!user) return <Login onLogin={handleLogin} />;
    switch (currentPage) {
      case '/': return <Dashboard user={user} />;
      case '/consultants': return <Consultants currentUser={user} />;
      case '/vendors': return <Vendors currentUser={user} />; // Yeni route
      case '/personnel': return <PersonnelPage currentUser={user} />;
      case '/transactions': return <Transactions currentUser={user} />;
      case '/expenses': return <Expenses currentUser={user} />;
      case '/reports': return <Reports />;
      case '/settings': return <Settings currentUser={user} />;
      default: return <Dashboard user={user} />;
    }
  };

  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <Layout user={user} onLogout={handleLogout} currentPage={currentPage} onNavigate={setCurrentPage}>
      {renderPage()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Vendor, Expense, User, SystemLog, ExpenseCategory } from '../types';
import { INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Building, Plus, Search, Phone, Mail, FileText, Wallet, ArrowRight, User as UserIcon, AlertCircle, Calendar, Receipt, ChevronRight } from 'lucide-react';

interface VendorsProps {
  currentUser: User;
}

const Vendors: React.FC<VendorsProps> = ({ currentUser }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Vendor>>({
    name: '',
    contactPerson: '',
    phone: '',
    email: '',
    taxNumber: '',
    taxOffice: '',
    category: ExpenseCategory.OTHER,
  });

  useEffect(() => {
    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);

    const storedExpenses = localStorage.getItem('emlak_expenses');
    setExpenses(storedExpenses ? JSON.parse(storedExpenses) : []);
  }, []);

  useEffect(() => {
    if (vendors.length > 0) localStorage.setItem('emlak_vendors', JSON.stringify(vendors));
  }, [vendors]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'VENDOR',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const getUnpaidExpensesByVendor = (vendorId: string) => {
    return expenses.filter(e => e.vendorId === vendorId && !e.isPaid);
  };

  const getVendorBalance = (vendorId: string) => {
    return getUnpaidExpensesByVendor(vendorId).reduce((acc, curr) => acc + curr.amount, 0);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const handleOpenModal = (vendor?: Vendor) => {
    if (vendor) {
      setEditingId(vendor.id);
      setFormData({ ...vendor });
    } else {
      setEditingId(null);
      setFormData({ name: '', contactPerson: '', phone: '', email: '', category: ExpenseCategory.OTHER });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setVendors(prev => prev.map(v => v.id === editingId ? { ...v, ...formData } as Vendor : v));
      logAction('UPDATE', `Firma Bilgisi Güncellendi: ${formData.name}`);
    } else {
      const newVendor: Vendor = { id: Date.now().toString(), ...formData as Omit<Vendor, 'id'> };
      setVendors(prev => [...prev, newVendor]);
      logAction('CREATE', `Yeni Firma/Tedarikçi Eklendi: ${newVendor.name}`);
    }
    setIsModalOpen(false);
  };

  const filteredVendors = vendors.filter(v => v.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Firmalar & Cariler</h1>
          <p className="text-slate-500">Hizmet alınan tedarikçileri ve borç bakiyelerini yönetin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Firma Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-3 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Firma adı ile ara..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVendors.map(vendor => {
          const unpaidItems = getUnpaidExpensesByVendor(vendor.id);
          const balance = unpaidItems.reduce((acc, curr) => acc + curr.amount, 0);

          return (
            <div key={vendor.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col">
              <div className="p-6 flex-1">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-3 bg-slate-50 rounded-xl text-slate-600 transition-colors">
                    <Building size={24} />
                  </div>
                  {balance > 0 && (
                    <span className="flex items-center gap-1 text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-1 rounded-full border border-orange-100 uppercase tracking-tighter">
                      <AlertCircle size={12} /> {unpaidItems.length} Bekleyen Fatura
                    </span>
                  )}
                </div>

                <h3 className="text-lg font-bold text-slate-900 truncate mb-1">{vendor.name}</h3>
                <p className="text-xs text-slate-500 flex items-center gap-1 mb-4">
                  <UserIcon size={12} /> {vendor.contactPerson || 'Yetkili belirtilmedi'}
                </p>

                <div className="space-y-2 mb-6">
                  <div className="flex items-center gap-2 text-sm text-slate-600">
                    <Phone size={14} className="text-slate-400" />
                    <span>{vendor.phone}</span>
                  </div>
                  {vendor.email && (
                    <div className="flex items-center gap-2 text-sm text-slate-600">
                      <Mail size={14} className="text-slate-400" />
                      <span>{vendor.email}</span>
                    </div>
                  )}
                </div>

                {/* Unpaid Items Detail Section */}
                {unpaidItems.length > 0 && (
                  <div className="mt-2 space-y-2">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 border-b border-slate-100 pb-1">Açık Hesap Kalemleri</p>
                    <div className="max-h-32 overflow-y-auto space-y-1 pr-1 custom-scrollbar">
                      {unpaidItems.map(item => (
                        <div key={item.id} className="flex justify-between items-center text-xs p-2 bg-slate-50 rounded border border-slate-100">
                          <div className="flex flex-col gap-0.5 max-w-[70%]">
                            <span className="font-bold text-slate-700 truncate" title={item.description}>{item.description}</span>
                            <span className="text-[9px] text-slate-400 font-mono">{new Date(item.date).toLocaleDateString('tr-TR')}</span>
                          </div>
                          <span className="font-black text-orange-600 whitespace-nowrap">{formatCurrency(item.amount)}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Footer */}
              <div className="px-6 py-4 bg-slate-50/50 border-t border-slate-100 flex items-center justify-between mt-auto">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase">Toplam Borç</p>
                  <p className={`text-xl font-black ${balance > 0 ? 'text-orange-600' : 'text-slate-400'}`}>
                    {formatCurrency(balance)}
                  </p>
                </div>
                <div className="flex gap-1">
                  <button 
                    onClick={() => handleOpenModal(vendor)} 
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100"
                    title="Firma Bilgilerini Düzenle"
                  >
                    <FileText size={20} />
                  </button>
                  {balance > 0 && (
                    <button 
                      onClick={() => window.location.hash = '/expenses'} 
                      className="p-2 text-orange-400 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-colors border border-transparent hover:border-orange-100"
                      title="Ödemeleri Yap"
                    >
                      <ChevronRight size={20} />
                    </button>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Firma Düzenle' : 'Yeni Firma Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Firma Adı</label>
            <input required type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Yetkili Kişi</label>
              <input type="text" value={formData.contactPerson} onChange={e => setFormData({...formData, contactPerson: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
