        </div>

        {/* Footer Actions (Screen Only) */}
        {!isPaid && (
          <div className="bg-slate-50 border-t border-slate-100 p-4 flex justify-end gap-3 print:hidden">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
