import React, { useState, useEffect } from 'react';
import { Expense, ExpenseCategory, Payer, User, SystemLog, Vendor } from '../types';
import { INITIAL_EXPENSES, INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Plus, Search, Filter, Receipt, Calendar, Tag, UserCircle, Building2, RefreshCw, FileText, PieChart, StickyNote, Trash2, Edit, AlertCircle, CheckCircle, Clock, Building, User as UserIcon } from 'lucide-react';

interface ExpensesProps {
  currentUser: User;
}

const Expenses: React.FC<ExpensesProps> = ({ currentUser }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL'); 

  // Form State
  const [formData, setFormData] = useState({
    description: '',
    category: ExpenseCategory.OTHER,
    amount: '',
    date: new Date().toISOString().split('T')[0],
    paidBy: Payer.OFFICE,
    notes: '',
    isPaid: true,
    vendorId: '',
  });

  // Load Data
  useEffect(() => {
    const storedExpenses = localStorage.getItem('emlak_expenses');
    if (storedExpenses) {
      setExpenses(JSON.parse(storedExpenses));
    } else {
      const initialWithStatus = INITIAL_EXPENSES.map(e => ({ ...e, isPaid: true }));
      setExpenses(initialWithStatus);
      localStorage.setItem('emlak_expenses', JSON.stringify(initialWithStatus));
    }

    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);
  }, []);

  // Save Data
  useEffect(() => {
    if (expenses.length > 0) {
      localStorage.setItem('emlak_expenses', JSON.stringify(expenses));
    }
  }, [expenses]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'EXPENSE',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const handleOpenModal = (expenseToEdit?: Expense) => {
    if (expenseToEdit) {
      setEditingId(expenseToEdit.id);
      setFormData({
        description: expenseToEdit.description,
        category: expenseToEdit.category,
        amount: expenseToEdit.amount.toString(),
        date: expenseToEdit.date,
        paidBy: expenseToEdit.paidBy,
        notes: expenseToEdit.notes || '',
        isPaid: expenseToEdit.isPaid,
        vendorId: expenseToEdit.vendorId || '',
      });
    } else {
      setEditingId(null);
      setFormData({
        description: '',
        category: ExpenseCategory.OTHER,
        amount: '',
        date: new Date().toISOString().split('T')[0],
        paidBy: Payer.OFFICE,
        notes: '',
        isPaid: true,
        vendorId: '',
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setExpenses(prev => prev.map(exp => 
        exp.id === editingId ? {
          ...exp,
          description: formData.description,
          category: formData.category,
          amount: Number(formData.amount),
          date: formData.date,
          paidBy: formData.paidBy,
          notes: formData.notes,
          isPaid: formData.isPaid,
          vendorId: formData.vendorId || undefined,
        } : exp
      ));
      logAction('UPDATE', `Gider Düzenlendi: ${formData.description}`);
    } else {
      const newExpense: Expense = {
        id: Date.now().toString(),
        description: formData.description,
        category: formData.category,
        amount: Number(formData.amount),
        date: formData.date,
        paidBy: formData.paidBy,
        notes: formData.notes,
        isPaid: formData.isPaid,
        vendorId: formData.vendorId || undefined,
      };
      setExpenses(prev => [newExpense, ...prev]);
      logAction('CREATE', `Yeni Gider: ${formData.description} (${formData.paidBy} tarafından)`);
    }
    setIsModalOpen(false);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const getVendorName = (vendorId?: string) => {
    if (!vendorId) return '-';
    return vendors.find(v => v.id === vendorId)?.name || 'Bilinmeyen Firma';
  };

  const getCategoryLabel = (cat: string) => {
    const labels: any = {
      [ExpenseCategory.RENT]: 'Kira',
      [ExpenseCategory.OFFICE_SUPPLIES]: 'Ofis Malzemeleri',
      [ExpenseCategory.MARKETING]: 'Pazarlama/İlan',
      [ExpenseCategory.UTILITIES]: 'Faturalar',
      [ExpenseCategory.FOOD]: 'Yemek/Temsil',
      [ExpenseCategory.PERSONNEL]: 'Personel Maaş',
      [ExpenseCategory.OTHER]: 'Diğer',
    };
    return labels[cat] || cat;
  };

  const getPayerLabel = (payer: Payer) => {
    switch(payer) {
      case Payer.ALTAN: return 'Altan';
      case Payer.SUAT: return 'Suat';
      case Payer.OFFICE: return 'Ofis Kasası';
      default: return payer;
    }
  };

  const filteredExpenses = expenses.filter(e => {
    const matchesSearch = e.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || e.category === filterCategory;
    const matchesStatus = filterStatus === 'ALL' || (filterStatus === 'PAID' ? e.isPaid : !e.isPaid);
    return matchesSearch && matchesCategory && matchesStatus;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Gider Yönetimi</h1>
          <p className="text-slate-500">Ofis harcamalarını ve ortakların yaptığı ödemeleri takip edin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-rose-600 hover:bg-rose-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Yeni Gider Ekle</span>
        </button>
      </div>

      <div className="flex gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-3 text-slate-400" size={20} />
          <input type="text" placeholder="Giderlerde ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-rose-500 shadow-sm" />
        </div>
        <button onClick={() => setShowFilters(!showFilters)} className={`px-4 py-2 border rounded-xl flex items-center gap-2 transition-colors ${showFilters ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-200 text-slate-600'}`}>
          <Filter size={20} />
          <span className="hidden sm:inline">Filtrele</span>
        </button>
      </div>

      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 font-semibold text-slate-700">Tarih</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Ödeyen / Cari</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Açıklama</th>
                <th className="px-6 py-4 font-semibold text-slate-700 text-right">Tutar</th>
                <th className="px-6 py-4 font-semibold text-slate-700 text-center">Durum</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredExpenses.map((expense) => (
                <tr key={expense.id} onClick={() => handleOpenModal(expense)} className="hover:bg-slate-50/50 transition-colors cursor-pointer group">
                  <td className="px-6 py-4 text-slate-500">{new Date(expense.date).toLocaleDateString('tr-TR')}</td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter mb-0.5">{getPayerLabel(expense.paidBy)}</span>
                        <span className="font-bold text-slate-800">{getVendorName(expense.vendorId)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">
                    <div className="flex items-center gap-2">
                        <span className="px-1.5 py-0.5 bg-slate-100 text-[9px] font-bold text-slate-500 rounded uppercase">{getCategoryLabel(expense.category)}</span>
                        {expense.description}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right font-black text-rose-600">-{formatCurrency(expense.amount)}</td>
                  <td className="px-6 py-4 text-center">
                    {expense.isPaid ? (
                        <span className="inline-flex items-center gap-1 text-emerald-600 font-bold text-[10px] uppercase"><CheckCircle size={14} /> Ödendi</span>
                    ) : (
                        <span className="inline-flex items-center gap-1 text-orange-600 font-bold text-[10px] uppercase"><Clock size={14} /> Bekliyor</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Gider Düzenle' : 'Yeni Gider Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700">Ödemeyi Yapan</label>
                <select 
                    value={formData.paidBy} 
                    onChange={e => setFormData({...formData, paidBy: e.target.value as Payer})}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none bg-indigo-50/30 font-semibold text-slate-800"
                >
                    <option value={Payer.OFFICE}>Ofis Kasası</option>
                    <option value={Payer.ALTAN}>Altan (Ortak)</option>
                    <option value={Payer.SUAT}>Suat (Ortak)</option>
                </select>
            </div>
            <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700">Firma / Cari</label>
                <select value={formData.vendorId} onChange={e => setFormData({...formData, vendorId: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none bg-white">
                <option value="">Firma Seçilmedi</option>
                {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                </select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Açıklama</label>
            <input required type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-rose-500" placeholder="Örn: Ekim Ayı Elektrik Faturası" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Kategori</label>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as ExpenseCategory})} className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white">
                {Object.values(ExpenseCategory).map(cat => <option key={cat} value={cat}>{getCategoryLabel(cat)}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Tarih</label>
              <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Tutar</label>
            <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400 font-bold">₺</span>
                <input required type="number" min="0" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg outline-none font-bold text-lg text-rose-600" placeholder="0.00" />
            </div>
          </div>

          <div className="space-y-1.5 pt-2">
            <label className="text-sm font-medium text-slate-700">Ödeme Durumu</label>
            <div className="grid grid-cols-2 gap-2">
                <button type="button" onClick={() => setFormData({...formData, isPaid: true})} className={`py-2 rounded-lg border text-sm font-bold transition-all ${formData.isPaid ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-slate-400 border-slate-200'}`}>Ödendi / Kapalı</button>
                <button type="button" onClick={() => setFormData({...formData, isPaid: false})} className={`py-2 rounded-lg border text-sm font-bold transition-all ${!formData.isPaid ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-slate-400 border-slate-200'}`}>Borç Kaydet / Açık</button>
            </div>
          </div>

          <div className="pt-4 flex gap-3">
             <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 text-slate-600 font-medium hover:bg-slate-50 rounded-lg">İptal</button>
             <button type="submit" className="flex-[2] py-3 bg-rose-600 text-white rounded-lg font-bold shadow-lg shadow-rose-900/20 active:scale-95 transition-transform">
                 {editingId ? 'Güncelle' : 'Gideri Kaydet'}
             </button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Expenses;

import React, { useState } from 'react';
import { MOCK_USERS } from '../constants';
import { User } from '../types';
import { Building2, Lock, User as UserIcon, AlertCircle } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    // Simulate network delay
    setTimeout(() => {
      // Simple mock authentication
      const user = MOCK_USERS.find(u => u.username === username);

      if (user && password === '1234') { // Mock password for everyone
        onLogin(user);
      } else {
        setError('Kullanıcı adı veya şifre hatalı.');
        setIsLoading(false);
      }
    }, 600);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-100 to-slate-200 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-xl overflow-hidden">
        {/* Header Section */}
        <div className="bg-slate-900 p-8 text-center">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-lg transform -rotate-3">
            <Building2 className="text-white w-8 h-8" />
          </div>
          <h1 className="text-2xl font-bold text-white mb-2">Emlak Ofisi YS</h1>
          <p className="text-slate-400 text-sm">Muhasebe ve Danışman Yönetim Paneli</p>
        </div>

        {/* Form Section */}
        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3 text-red-600 text-sm">
                <AlertCircle size={18} />
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-700 block">Kullanıcı Adı</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                  <UserIcon size={18} />
                </div>
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="block w-full pl-10 pr-3 py-2.5 bg-white text-slate-900 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent transition-all outline-none"
                  placeholder="Kullanıcı adınızı girin"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-700 block">Şifre</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                  <Lock size={18} />
                </div>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-10 pr-3 py-2.5 bg-white text-slate-900 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent transition-all outline-none"
                  placeholder="••••••••"
                  required
                />
              </div>
              <p className="text-xs text-slate-500 text-right pt-1">Varsayılan şifre: 1234</p>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className={`
                w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-lg shadow-md hover:shadow-lg transition-all
                focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-600
                ${isLoading ? 'opacity-70 cursor-not-allowed' : ''}
              `}
            >
              {isLoading ? 'Giriş Yapılıyor...' : 'Giriş Yap'}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-100">
            <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-wider text-center mb-4">
              Yetkili Hesaplar (Demo)
            </h4>
            <div className="grid grid-cols-3 gap-2">
              {MOCK_USERS.map(u => (
                <button
                  key={u.id}
                  onClick={() => {
                    setUsername(u.username);
                    setPassword('1234');
                  }}
                  className="text-xs py-2 px-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-slate-600 transition-colors truncate"
                  title={u.name}
                >
                  {u.username}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { Expense, ExpenseCategory, Payer, User, SystemLog, Vendor } from '../types';
import { INITIAL_EXPENSES, INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Plus, Search, Filter, Receipt, Calendar, Tag, UserCircle, Building2, RefreshCw, FileText, PieChart, StickyNote, Trash2, Edit, AlertCircle, CheckCircle, Clock, Building, User as UserIcon } from 'lucide-react';

interface ExpensesProps {
  currentUser: User;
}

const Expenses: React.FC<ExpensesProps> = ({ currentUser }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL'); 

  // Form State
  const [formData, setFormData] = useState({
    description: '',
    category: ExpenseCategory.OTHER,
    amount: '',
    date: new Date().toISOString().split('T')[0],
    paidBy: Payer.OFFICE,
    notes: '',
    isPaid: true,
    vendorId: '',
  });

  // Load Data
  useEffect(() => {
    const storedExpenses = localStorage.getItem('emlak_expenses');
    if (storedExpenses) {
      setExpenses(JSON.parse(storedExpenses));
    } else {
      const initialWithStatus = INITIAL_EXPENSES.map(e => ({ ...e, isPaid: true }));
      setExpenses(initialWithStatus);
      localStorage.setItem('emlak_expenses', JSON.stringify(initialWithStatus));
    }

    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);
  }, []);

  // Save Data
  useEffect(() => {
    if (expenses.length > 0) {
      localStorage.setItem('emlak_expenses', JSON.stringify(expenses));
    }
  }, [expenses]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'EXPENSE',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const handleOpenModal = (expenseToEdit?: Expense) => {
    if (expenseToEdit) {
      setEditingId(expenseToEdit.id);
      setFormData({
        description: expenseToEdit.description,
        category: expenseToEdit.category,
        amount: expenseToEdit.amount.toString(),
        date: expenseToEdit.date,
        paidBy: expenseToEdit.paidBy,
        notes: expenseToEdit.notes || '',
        isPaid: expenseToEdit.isPaid,
        vendorId: expenseToEdit.vendorId || '',
      });
    } else {
      setEditingId(null);
      setFormData({
        description: '',
        category: ExpenseCategory.OTHER,
        amount: '',
        date: new Date().toISOString().split('T')[0],
        paidBy: Payer.OFFICE,
        notes: '',
        isPaid: true,
        vendorId: '',
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setExpenses(prev => prev.map(exp => 
        exp.id === editingId ? {
          ...exp,
          description: formData.description,
          category: formData.category,
          amount: Number(formData.amount),
          date: formData.date,
          paidBy: formData.paidBy,
          notes: formData.notes,
          isPaid: formData.isPaid,
          vendorId: formData.vendorId || undefined,
        } : exp
      ));
      logAction('UPDATE', `Gider Düzenlendi: ${formData.description}`);
    } else {
      const newExpense: Expense = {
        id: Date.now().toString(),
        description: formData.description,
        category: formData.category,
        amount: Number(formData.amount),
        date: formData.date,
        paidBy: formData.paidBy,
        notes: formData.notes,
        isPaid: formData.isPaid,
        vendorId: formData.vendorId || undefined,
      };
      setExpenses(prev => [newExpense, ...prev]);
      logAction('CREATE', `Yeni Gider: ${formData.description} (${formData.paidBy} tarafından)`);
    }
    setIsModalOpen(false);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const getVendorName = (vendorId?: string) => {
    if (!vendorId) return '-';
    return vendors.find(v => v.id === vendorId)?.name || 'Bilinmeyen Firma';
  };

  const getCategoryLabel = (cat: string) => {
    const labels: any = {
      [ExpenseCategory.RENT]: 'Kira',
      [ExpenseCategory.OFFICE_SUPPLIES]: 'Ofis Malzemeleri',
      [ExpenseCategory.MARKETING]: 'Pazarlama/İlan',
      [ExpenseCategory.UTILITIES]: 'Faturalar',
      [ExpenseCategory.FOOD]: 'Yemek/Temsil',
      [ExpenseCategory.PERSONNEL]: 'Personel Maaş',
      [ExpenseCategory.OTHER]: 'Diğer',
    };
    return labels[cat] || cat;
  };

  const getPayerLabel = (payer: Payer) => {
    switch(payer) {
      case Payer.ALTAN: return 'Altan';
      case Payer.SUAT: return 'Suat';
      case Payer.OFFICE: return 'Ofis Kasası';
      default: return payer;
    }
  };

  const filteredExpenses = expenses.filter(e => {
    const matchesSearch = e.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || e.category === filterCategory;
    const matchesStatus = filterStatus === 'ALL' || (filterStatus === 'PAID' ? e.isPaid : !e.isPaid);
    return matchesSearch && matchesCategory && matchesStatus;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Gider Yönetimi</h1>
          <p className="text-slate-500">Ofis harcamalarını ve ortakların yaptığı ödemeleri takip edin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-rose-600 hover:bg-rose-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Yeni Gider Ekle</span>
        </button>
      </div>

      <div className="flex gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-3 text-slate-400" size={20} />
          <input type="text" placeholder="Giderlerde ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-white text-slate-900 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-rose-500 shadow-sm" />
        </div>
        <button onClick={() => setShowFilters(!showFilters)} className={`px-4 py-2 border rounded-xl flex items-center gap-2 transition-colors ${showFilters ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-200 text-slate-600'}`}>
          <Filter size={20} />
          <span className="hidden sm:inline">Filtrele</span>
        </button>
      </div>

      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 font-semibold text-slate-700">Tarih</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Ödeyen / Cari</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Açıklama</th>
                <th className="px-6 py-4 font-semibold text-slate-700 text-right">Tutar</th>
                <th className="px-6 py-4 font-semibold text-slate-700 text-center">Durum</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredExpenses.map((expense) => (
                <tr key={expense.id} onClick={() => handleOpenModal(expense)} className="hover:bg-slate-50/50 transition-colors cursor-pointer group">
                  <td className="px-6 py-4 text-slate-500">{new Date(expense.date).toLocaleDateString('tr-TR')}</td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter mb-0.5">{getPayerLabel(expense.paidBy)}</span>
                        <span className="font-bold text-slate-800">{getVendorName(expense.vendorId)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">
                    <div className="flex items-center gap-2">
                        <span className="px-1.5 py-0.5 bg-slate-100 text-[9px] font-bold text-slate-500 rounded uppercase">{getCategoryLabel(expense.category)}</span>
                        {expense.description}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right font-black text-rose-600">-{formatCurrency(expense.amount)}</td>
                  <td className="px-6 py-4 text-center">
                    {expense.isPaid ? (
                        <span className="inline-flex items-center gap-1 text-emerald-600 font-bold text-[10px] uppercase"><CheckCircle size={14} /> Ödendi</span>
                    ) : (
                        <span className="inline-flex items-center gap-1 text-orange-600 font-bold text-[10px] uppercase"><Clock size={14} /> Bekliyor</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Gider Düzenle' : 'Yeni Gider Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700">Ödemeyi Yapan</label>
                <select 
                    value={formData.paidBy} 
                    onChange={e => setFormData({...formData, paidBy: e.target.value as Payer})}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none bg-white text-slate-900 font-semibold"
                >
                    <option value={Payer.OFFICE}>Ofis Kasası</option>
                    <option value={Payer.ALTAN}>Altan (Ortak)</option>
                    <option value={Payer.SUAT}>Suat (Ortak)</option>
                </select>
            </div>
            <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700">Firma / Cari</label>
                <select value={formData.vendorId} onChange={e => setFormData({...formData, vendorId: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg outline-none bg-white text-slate-900">
                <option value="">Firma Seçilmedi</option>
                {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                </select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Açıklama</label>
            <input required type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-rose-500" placeholder="Örn: Ekim Ayı Elektrik Faturası" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Kategori</label>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as ExpenseCategory})} className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900">
                {Object.values(ExpenseCategory).map(cat => <option key={cat} value={cat}>{getCategoryLabel(cat)}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Tarih</label>
              <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Tutar</label>
            <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400 font-bold">₺</span>
                <input required type="number" min="0" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full pl-8 pr-3 py-2 bg-white text-rose-600 border border-slate-300 rounded-lg outline-none font-bold text-lg" placeholder="0.00" />
            </div>
          </div>

          <div className="space-y-1.5 pt-2">
            <label className="text-sm font-medium text-slate-700">Ödeme Durumu</label>
            <div className="grid grid-cols-2 gap-2">
                <button type="button" onClick={() => setFormData({...formData, isPaid: true})} className={`py-2 rounded-lg border text-sm font-bold transition-all ${formData.isPaid ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-slate-400 border-slate-200'}`}>Ödendi / Kapalı</button>
                <button type="button" onClick={() => setFormData({...formData, isPaid: false})} className={`py-2 rounded-lg border text-sm font-bold transition-all ${!formData.isPaid ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-slate-400 border-slate-200'}`}>Borç Kaydet / Açık</button>
            </div>
          </div>

          <div className="pt-4 flex gap-3">
             <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 text-slate-600 font-medium hover:bg-slate-50 rounded-lg">İptal</button>
             <button type="submit" className="flex-[2] py-3 bg-rose-600 text-white rounded-lg font-bold shadow-lg shadow-rose-900/20 active:scale-95 transition-transform">
                 {editingId ? 'Güncelle' : 'Gideri Kaydet'}
             </button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Expenses;

import React, { useState, useEffect, useMemo } from 'react';
import { Vendor, Expense, User, SystemLog, ExpenseCategory } from '../types';
import { INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Building, Plus, Search, Phone, Mail, FileText, Wallet, ArrowRight, User as UserIcon, AlertCircle, Calendar, Receipt, ChevronRight } from 'lucide-react';

interface VendorsProps {
  currentUser: User;
}

const Vendors: React.FC<VendorsProps> = ({ currentUser }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Vendor>>({
    name: '',
    contactPerson: '',
    phone: '',
    email: '',
    taxNumber: '',
    taxOffice: '',
    category: ExpenseCategory.OTHER,
  });

  useEffect(() => {
    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);

    const storedExpenses = localStorage.getItem('emlak_expenses');
    setExpenses(storedExpenses ? JSON.parse(storedExpenses) : []);
  }, []);

  useEffect(() => {
    if (vendors.length > 0) localStorage.setItem('emlak_vendors', JSON.stringify(vendors));
  }, [vendors]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'VENDOR',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const getUnpaidExpensesByVendor = (vendorId: string) => {
    return expenses.filter(e => e.vendorId === vendorId && !e.isPaid);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const handleOpenModal = (vendor?: Vendor) => {
    if (vendor) {
      setEditingId(vendor.id);
      setFormData({ ...vendor });
    } else {
      setEditingId(null);
      setFormData({ name: '', contactPerson: '', phone: '', email: '', category: ExpenseCategory.OTHER });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setVendors(prev => prev.map(v => v.id === editingId ? { ...v, ...formData } as Vendor : v));
      logAction('UPDATE', `Firma Bilgisi Güncellendi: ${formData.name}`);
    } else {
      const newVendor: Vendor = { id: Date.now().toString(), ...formData as Omit<Vendor, 'id'> };
      setVendors(prev => [...prev, newVendor]);
      logAction('CREATE', `Yeni Firma/Tedarikçi Eklendi: ${newVendor.name}`);
    }
    setIsModalOpen(false);
  };

  const filteredVendors = vendors.filter(v => v.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Firmalar & Cariler</h1>
          <p className="text-slate-500">Hizmet alınan tedarikçileri ve borç bakiyelerini yönetin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Firma Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-3 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Firma adı ile ara..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="w-full pl-10 pr-4 py-3 bg-white text-slate-900 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVendors.map(vendor => {
          const unpaidItems = getUnpaidExpensesByVendor(vendor.id);
          const balance = unpaidItems.reduce((acc, curr) => acc + curr.amount, 0);

          return (
            <div key={vendor.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col">
              <div className="p-6 flex-1">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-3 bg-slate-50 rounded-xl text-slate-600 transition-colors">
                    <Building size={24} />
                  </div>
                  {balance > 0 && (
                    <span className="flex items-center gap-1 text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-1 rounded-full border border-orange-100 uppercase tracking-tighter">
                      <AlertCircle size={12} /> {unpaidItems.length} Bekleyen Fatura
                    </span>
                  )}
                </div>

                <h3 className="text-lg font-bold text-slate-900 truncate mb-1">{vendor.name}</h3>
                <p className="text-xs text-slate-500 flex items-center gap-1 mb-4">
                  <UserIcon size={12} /> {vendor.contactPerson || 'Yetkili belirtilmedi'}
                </p>

                <div className="space-y-2 mb-6 text-sm text-slate-600">
                  <div className="flex items-center gap-2">
                    <Phone size={14} className="text-slate-400" />
                    <span>{vendor.phone}</span>
                  </div>
                  {vendor.email && (
                    <div className="flex items-center gap-2">
                      <Mail size={14} className="text-slate-400" />
                      <span>{vendor.email}</span>
                    </div>
                  )}
                </div>
              </div>

              <div className="px-6 py-4 bg-slate-50/50 border-t border-slate-100 flex items-center justify-between mt-auto">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase">Toplam Borç</p>
                  <p className={`text-xl font-black ${balance > 0 ? 'text-orange-600' : 'text-slate-400'}`}>
                    {formatCurrency(balance)}
                  </p>
                </div>
                <div className="flex gap-1">
                  <button 
                    onClick={() => handleOpenModal(vendor)} 
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100"
                  >
                    <FileText size={20} />
                  </button>
                </div>
              </div>
            </div>
