import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { Building2, Lock, User as UserIcon, AlertCircle, UserPlus, LogIn } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.PARTNER);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Initialize users in localStorage if not exists
  useEffect(() => {
    const storedUsers = localStorage.getItem('emlak_auth_users');
    if (!storedUsers) {
      localStorage.setItem('emlak_auth_users', JSON.stringify([]));
    }
  }, []);

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    setTimeout(() => {
      const storedUsersRaw = localStorage.getItem('emlak_auth_users');
      const users: any[] = storedUsersRaw ? JSON.parse(storedUsersRaw) : [];

      if (isRegistering) {
        // Register Logic
        if (users.find(u => u.username === username.toLowerCase())) {
          setError('Bu kullanıcı adı zaten alınmış.');
          setIsLoading(false);
          return;
        }

        const newUser = {
          id: Date.now().toString(),
          username: username.toLowerCase(),
          password: password, // In a real app, hash this!
          name: name,
          role: role
        };

        users.push(newUser);
        localStorage.setItem('emlak_auth_users', JSON.stringify(users));

        // Auto login after register
        const { password: _, ...userSession } = newUser;
        onLogin(userSession as User);
      } else {
        // Login Logic
        const user = users.find(u => u.username === username.toLowerCase() && u.password === password);

        if (user) {
          const { password: _, ...userSession } = user;
          onLogin(userSession as User);
        } else {
          setError('Kullanıcı adı veya şifre hatalı.');
          setIsLoading(false);
        }
      }
    }, 800);
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden border border-slate-200">
        {/* Header */}
        <div className="bg-slate-900 p-8 text-center">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-lg transform -rotate-3 transition-transform hover:rotate-0">
            <Building2 className="text-white w-8 h-8" />
          </div>
          <h1 className="text-2xl font-bold text-white mb-1">Emlak Ofisi YS</h1>
          <p className="text-slate-400 text-sm">Muhasebe Yönetim Paneli</p>
        </div>

        {/* Tab Switcher */}
        <div className="flex border-b border-slate-100">
          <button 
            onClick={() => { setIsRegistering(false); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors ${!isRegistering ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/30' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <LogIn size={18} /> Giriş Yap
          </button>
          <button 
            onClick={() => { setIsRegistering(true); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors ${isRegistering ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/30' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <UserPlus size={18} /> Hesap Oluştur
          </button>
        </div>

        {/* Form */}
        <div className="p-8">
          <form onSubmit={handleAuth} className="space-y-5">
            {error && (
              <div className="p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3 text-red-600 text-xs font-bold animate-shake">
                <AlertCircle size={16} />
                {error}
              </div>
            )}

            {isRegistering && (
              <>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase">Ad Soyad</label>
                  <input
                    type="text"
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="block w-full px-4 py-3 bg-white text-slate-900 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                    placeholder="Adınızı girin"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase">Yetki Rolü</label>
                  <select
                    value={role}
                    onChange={(e) => setRole(e.target.value as UserRole)}
                    className="block w-full px-4 py-3 bg-white text-slate-900 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-600 outline-none"
                  >
                    <option value={UserRole.PARTNER}>Ortak (Tam Yetki)</option>
                    <option value={UserRole.ACCOUNTANT}>Muhasebe (Sınırlı Yetki)</option>
                  </select>
                </div>
              </>
            )}

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 uppercase">Kullanıcı Adı</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <UserIcon size={18} />
                </div>
                <input
                  type="text"
                  required
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="block w-full pl-11 pr-4 py-3 bg-white text-slate-900 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                  placeholder="Kullanıcı adı"
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 uppercase">Şifre</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <Lock size={18} />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-11 pr-4 py-3 bg-white text-slate-900 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                  placeholder="••••••••"
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className={`
                w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-[0.98]
                ${isLoading ? 'opacity-70 cursor-not-allowed' : ''}
              `}
            >
              {isLoading ? 'Lütfen bekleyin...' : (isRegistering ? 'Kaydı Tamamla' : 'Sisteme Giriş Yap')}
            </button>
          </form>

          <p className="mt-8 text-center text-xs text-slate-400 leading-relaxed px-4">
