import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { Building2, Lock, User as UserIcon, AlertCircle, LogIn } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Uygulama ilk çalıştığında yetkili kullanıcıları tanımla
  useEffect(() => {
    const predefinedUsers = [
      { id: 'u1', username: 'altan', password: 'altan2025', name: 'Altan Bey', role: UserRole.PARTNER },
      { id: 'u2', username: 'suat', password: 'suat2025', name: 'Suat Bey', role: UserRole.PARTNER },
      { id: 'u3', username: 'nalan', password: 'nalan2025', name: 'Nalan Hanım', role: UserRole.ACCOUNTANT }
    ];

    // Sadece henüz kullanıcılar tanımlanmamışsa localStorage'a ekle
    const stored = localStorage.getItem('emlak_auth_users');
    if (!stored || JSON.parse(stored).length === 0) {
      localStorage.setItem('emlak_auth_users', JSON.stringify(predefinedUsers));
    }
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    // Ağ gecikmesi simülasyonu
    setTimeout(() => {
      const storedUsersRaw = localStorage.getItem('emlak_auth_users');
      const users: any[] = storedUsersRaw ? JSON.parse(storedUsersRaw) : [];

      const user = users.find(u => 
        u.username === username.toLowerCase().trim() && 
        u.password === password
      );

      if (user) {
        // Şifreyi session verisinden çıkararak login yap
        const { password: _, ...userSession } = user;
        onLogin(userSession as User);
      } else {
        setError('Kullanıcı adı veya şifre hatalı.');
        setIsLoading(false);
      }
    }, 600);
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
        {/* Modern Header */}
        <div className="bg-slate-900 p-10 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500"></div>
          <div className="w-20 h-20 bg-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl transform transition-transform hover:scale-105">
            <Building2 className="text-white w-10 h-10" />
          </div>
          <h1 className="text-3xl font-black text-white tracking-tight">Emlak Ofisi YS</h1>
          <p className="text-slate-400 text-sm mt-2 font-medium">Kurumsal Muhasebe Yönetimi</p>
        </div>

        {/* Login Form Container */}
        <div className="p-10">
          <div className="flex items-center gap-2 mb-8 text-slate-800">
            <LogIn size={20} className="text-indigo-600" />
            <span className="font-bold text-lg">Yetkili Girişi</span>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-xl flex items-center gap-3 text-red-600 text-xs font-bold animate-in fade-in slide-in-from-top-2">
                <AlertCircle size={18} className="shrink-0" />
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-1">Kullanıcı Adı</label>
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 group-focus-within:text-indigo-600 transition-colors">
                  <UserIcon size={20} />
                </div>
                <input
                  type="text"
                  required
                  autoFocus
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="block w-full pl-12 pr-4 py-4 bg-white text-slate-900 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:ring-0 outline-none transition-all font-medium placeholder:text-slate-300"
                  placeholder="Kullanıcı adınız"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-1">Şifre</label>
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 group-focus-within:text-indigo-600 transition-colors">
                  <Lock size={20} />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-12 pr-4 py-4 bg-white text-slate-900 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:ring-0 outline-none transition-all font-medium placeholder:text-slate-300"
                  placeholder="••••••••"
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className={`
                w-full py-4 bg-slate-900 hover:bg-black text-white font-black rounded-2xl shadow-xl shadow-slate-200 transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-2 text-lg
                ${isLoading ? 'opacity-70 cursor-not-allowed' : ''}
              `}
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  <span>Giriş Yapılıyor...</span>
                </>
              ) : (
                'Sisteme Eriş'
              )}
            </button>
          </form>

          <div className="mt-10 pt-6 border-t border-slate-50">
            <p className="text-center text-[10px] text-slate-400 leading-relaxed font-bold uppercase tracking-tighter">
              Bu sistem sadece yetkili personel içindir. <br/> Tüm işlemler kayıt altına alınmaktadır.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { Vendor, Expense, User, SystemLog, ExpenseCategory } from '../types';
import { INITIAL_VENDORS } from '../constants';
import Modal from '../components/Modal';
import { Building, Plus, Search, Phone, Mail, FileText, User as UserIcon, AlertCircle, Calendar, Receipt, ChevronDown, ChevronUp } from 'lucide-react';

interface VendorsProps {
  currentUser: User;
}

const Vendors: React.FC<VendorsProps> = ({ currentUser }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedVendorId, setExpandedVendorId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Vendor>>({
    name: '',
    contactPerson: '',
    phone: '',
    email: '',
    taxNumber: '',
    taxOffice: '',
    category: ExpenseCategory.OTHER,
  });

  useEffect(() => {
    const storedVendors = localStorage.getItem('emlak_vendors');
    setVendors(storedVendors ? JSON.parse(storedVendors) : INITIAL_VENDORS);

    const storedExpenses = localStorage.getItem('emlak_expenses');
    setExpenses(storedExpenses ? JSON.parse(storedExpenses) : []);
  }, []);

  useEffect(() => {
    if (vendors.length > 0) localStorage.setItem('emlak_vendors', JSON.stringify(vendors));
  }, [vendors]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'VENDOR',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const getUnpaidExpensesByVendor = (vendorId: string) => {
    return expenses.filter(e => e.vendorId === vendorId && !e.isPaid);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const handleOpenModal = (vendor?: Vendor) => {
    if (vendor) {
      setEditingId(vendor.id);
      setFormData({ ...vendor });
    } else {
      setEditingId(null);
      setFormData({ name: '', contactPerson: '', phone: '', email: '', category: ExpenseCategory.OTHER });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setVendors(prev => prev.map(v => v.id === editingId ? { ...v, ...formData } as Vendor : v));
      logAction('UPDATE', `Firma Bilgisi Güncellendi: ${formData.name}`);
    } else {
      const newVendor: Vendor = { id: Date.now().toString(), ...formData as Omit<Vendor, 'id'> };
      setVendors(prev => [...prev, newVendor]);
      logAction('CREATE', `Yeni Firma/Tedarikçi Eklendi: ${newVendor.name}`);
    }
    setIsModalOpen(false);
  };

  const toggleExpand = (vendorId: string) => {
    setExpandedVendorId(expandedVendorId === vendorId ? null : vendorId);
  };

  const filteredVendors = vendors.filter(v => v.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Firmalar & Cariler</h1>
          <p className="text-slate-500">Hizmet alınan tedarikçileri ve borç bakiyelerini yönetin.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Firma Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-3 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Firma adı ile ara..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="w-full pl-10 pr-4 py-3 bg-white text-slate-900 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 items-start">
        {filteredVendors.map(vendor => {
          const unpaidItems = getUnpaidExpensesByVendor(vendor.id);
          const balance = unpaidItems.reduce((acc, curr) => acc + curr.amount, 0);
          const isExpanded = expandedVendorId === vendor.id;

          return (
            <div key={vendor.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all overflow-hidden flex flex-col">
              <div className="p-6 pb-4">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-3 bg-slate-50 rounded-xl text-slate-600">
                    <Building size={24} />
                  </div>
                  {balance > 0 && (
                    <span className="flex items-center gap-1 text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-1 rounded-full border border-orange-100 uppercase tracking-tighter">
                      <AlertCircle size={12} /> {unpaidItems.length} Bekleyen Fatura
                    </span>
                  )}
                </div>

                <h3 className="text-lg font-bold text-slate-900 truncate mb-1">{vendor.name}</h3>
                <p className="text-xs text-slate-500 flex items-center gap-1 mb-4">
                  <UserIcon size={12} /> {vendor.contactPerson || 'Yetkili belirtilmedi'}
                </p>

                <div className="space-y-2 text-sm text-slate-600">
                  <div className="flex items-center gap-2">
                    <Phone size={14} className="text-slate-400" />
                    <span>{vendor.phone}</span>
                  </div>
                  {vendor.email && (
                    <div className="flex items-center gap-2">
                      <Mail size={14} className="text-slate-400" />
                      <span>{vendor.email}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Açık Hesap Detayları Bölümü */}
              {balance > 0 && (
                <div className="px-6 py-2">
                   <button 
                    onClick={() => toggleExpand(vendor.id)}
                    className="w-full flex items-center justify-between py-2 px-3 bg-slate-50 hover:bg-slate-100 rounded-lg text-xs font-bold text-slate-600 transition-colors"
                   >
                     <span className="flex items-center gap-2"><Receipt size={14} className="text-orange-500" /> AÇIK HESAP DETAYI</span>
                     {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                   </button>

                   {isExpanded && (
                     <div className="mt-2 space-y-2 animate-in slide-in-from-top-2 duration-200 overflow-hidden">
                        <div className="bg-slate-50/50 rounded-lg border border-slate-100 overflow-hidden">
                          <table className="w-full text-[11px] text-left">
                            <thead className="bg-slate-100/50 text-slate-400 uppercase font-black">
                              <tr>
                                <th className="px-3 py-2">Tarih</th>
                                <th className="px-3 py-2">Açıklama</th>
                                <th className="px-3 py-2 text-right">Tutar</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                              {unpaidItems.map(item => (
                                <tr key={item.id} className="text-slate-600">
                                  <td className="px-3 py-2 whitespace-nowrap">{new Date(item.date).toLocaleDateString('tr-TR')}</td>
                                  <td className="px-3 py-2 truncate max-w-[120px]">{item.description}</td>
                                  <td className="px-3 py-2 text-right font-bold text-slate-900">{formatCurrency(item.amount)}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                     </div>
                   )}
                </div>
              )}

              <div className="px-6 py-4 bg-slate-50/50 border-t border-slate-100 flex items-center justify-between mt-auto">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Toplam Bakiye</p>
                  <p className={`text-xl font-black ${balance > 0 ? 'text-orange-600' : 'text-slate-400'}`}>
                    {formatCurrency(balance)}
                  </p>
                </div>
                <div className="flex gap-1">
                  <button 
                    onClick={() => handleOpenModal(vendor)} 
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100"
                    title="Firma Bilgilerini Düzenle"
                  >
                    <FileText size={20} />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Firma Düzenle' : 'Yeni Firma Kaydı'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Firma Adı</label>
            <input required type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Yetkili Kişi</label>
              <input type="text" value={formData.contactPerson} onChange={e => setFormData({...formData, contactPerson: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Telefon</label>
              <input required type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">E-Posta</label>
            <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Vergi No</label>
              <input type="text" value={formData.taxNumber} onChange={e => setFormData({...formData, taxNumber: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Vergi Dairesi</label>
              <input type="text" value={formData.taxOffice} onChange={e => setFormData({...formData, taxOffice: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
            </div>
          </div>
          <div className="pt-4 flex gap-3">
            <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg font-medium">İptal</button>
            <button type="submit" className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold">Kaydet</button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Vendors;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, Consultant, PaymentStatus, User, SystemLog, Expense, ExpenseCategory, Payer } from '../types';
import { INITIAL_TRANSACTIONS, INITIAL_CONSULTANTS } from '../constants';
import Modal from '../components/Modal';
import PaymentFormModal from '../components/PaymentFormModal';
import { Plus, Search, Filter, TrendingUp, Building, User as UserIcon, FileText, CheckCircle2, Clock, Trash2, AlertCircle, Banknote } from 'lucide-react';

interface TransactionsProps {
  currentUser: User;
}

const Transactions: React.FC<TransactionsProps> = ({ currentUser }) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [consultants, setConsultants] = useState<Consultant[]>([]);

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);

  // Selection States for Actions
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);
  const [selectedConsultant, setSelectedConsultant] = useState<Consultant | null>(null);

  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState({
    propertyName: '',
    type: TransactionType.SALE,
    customerName: '',
    consultantId: '',
    date: new Date().toISOString().split('T')[0],
    totalRevenue: '',
  });

  // Load Data
  useEffect(() => {
    const storedTrans = localStorage.getItem('emlak_transactions');
    setTransactions(storedTrans ? JSON.parse(storedTrans) : INITIAL_TRANSACTIONS);

    const storedCons = localStorage.getItem('emlak_consultants');
    setConsultants(storedCons ? JSON.parse(storedCons) : INITIAL_CONSULTANTS);
  }, []);

  // Save Data
  useEffect(() => {
    // Sadece transactions dizisi doluysa veya en azından başlangıç dizisi boşsa bile kaydet (silme işlemi için önemli)
    if (transactions) { 
        localStorage.setItem('emlak_transactions', JSON.stringify(transactions));
    }
  }, [transactions]);

  const logAction = (action: 'CREATE' | 'UPDATE' | 'DELETE' | 'APPROVE', description: string) => {
    const newLog: SystemLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      user: currentUser.name,
      action: action,
      module: 'TRANSACTION',
      description: description
    };
    const storedLogs = localStorage.getItem('emlak_logs');
    let logs = storedLogs ? JSON.parse(storedLogs) : [];
    localStorage.setItem('emlak_logs', JSON.stringify([newLog, ...logs]));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const c = consultants.find(item => item.id === formData.consultantId);
    if (!c) {
        alert("Lütfen geçerli bir danışman seçiniz.");
        return;
    }

    const revenue = Number(formData.totalRevenue);
    const consultantShare = revenue * (c.commissionRate / 100);
    const officeRevenue = revenue - consultantShare;

    const newTransaction: Transaction = {
      id: Date.now().toString(),
      propertyName: formData.propertyName,
      type: formData.type,
      customerName: formData.customerName,
      consultantId: formData.consultantId,
      date: formData.date,
      totalRevenue: revenue,
      officeRevenue: officeRevenue,
      consultantShare: consultantShare,
      partnerShareAltan: officeRevenue / 2,
      partnerShareSuat: officeRevenue / 2,
      paymentStatus: PaymentStatus.PENDING,
    };

    setTransactions(prev => [newTransaction, ...prev]);
    logAction('CREATE', `Yeni İşlem: ${newTransaction.propertyName} (${formatCurrency(newTransaction.totalRevenue)})`);
    setIsModalOpen(false);

    // Form reset
    setFormData({
        propertyName: '',
        type: TransactionType.SALE,
        customerName: '',
        consultantId: '',
        date: new Date().toISOString().split('T')[0],
        totalRevenue: '',
    });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz? Bu işlem geri alınamaz.')) {
        setTransactions(prev => prev.filter(t => t.id !== id));
        logAction('DELETE', `İşlem Silindi: ID ${id}`);
    }
  };

  const handleOpenPaymentModal = (transaction: Transaction) => {
    const consultant = consultants.find(c => c.id === transaction.consultantId);
    if (consultant) {
        setSelectedTransaction(transaction);
        setSelectedConsultant(consultant);
        setIsPaymentModalOpen(true);
    } else {
        alert('Bu işlemin danışmanı sistemde bulunamadı.');
    }
  };

  const handleConfirmPayment = (transactionId: string) => {
    // 1. İşlemi Güncelle (ÖDENDİ Yap)
    const updatedTransactions = transactions.map(t => 
        t.id === transactionId ? { ...t, paymentStatus: PaymentStatus.PAID } : t
    );
    setTransactions(updatedTransactions);

    // 2. Gider Kaydı Oluştur (Otomatik)
    const transaction = transactions.find(t => t.id === transactionId);
    const consultant = consultants.find(c => c.id === transaction?.consultantId);

    if (transaction && consultant) {
        const newExpense: Expense = {
            id: `auto-exp-${Date.now()}`,
            category: ExpenseCategory.PERSONNEL, // Prim/Hakediş ödemesi
            amount: transaction.consultantShare,
            date: new Date().toISOString().split('T')[0],
            description: `Hakediş Ödemesi: ${transaction.propertyName} - ${consultant.fullName}`,
            paidBy: Payer.OFFICE, // Ödemeyi ofis yaptı varsayıyoruz
            isPaid: true,
            notes: `Ref İşlem ID: ${transaction.id}`
        };

        const storedExpenses = localStorage.getItem('emlak_expenses');
        const currentExpenses = storedExpenses ? JSON.parse(storedExpenses) : [];
        localStorage.setItem('emlak_expenses', JSON.stringify([newExpense, ...currentExpenses]));

        logAction('APPROVE', `Hakediş Ödendi ve Giderleşti: ${transaction.propertyName}`);
    }

    setIsPaymentModalOpen(false);
    alert('Hakediş ödemesi başarıyla onaylandı ve Giderler tablosuna işlendi.');
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  const filteredTransactions = transactions.filter(t => 
    t.propertyName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.customerName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
            <h1 className="text-2xl font-bold text-slate-900">İşlemler & Gelirler</h1>
            <p className="text-slate-500">Satış ve kiralama işlemlerini kaydedin, hakedişleri yönetin.</p>
        </div>
        <button onClick={() => setIsModalOpen(true)} className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-medium shadow-sm transition-colors">
          <Plus size={20} />
          <span>Yeni İşlem Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-3 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Mülk adı veya müşteri ara..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="w-full pl-10 pr-4 py-3 bg-white text-slate-900 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm" 
        />
      </div>

      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
                <thead>
                    <tr className="bg-slate-50 border-b border-slate-200">
                        <th className="px-6 py-4 font-semibold text-slate-700">Tarih</th>
                        <th className="px-6 py-4 font-semibold text-slate-700">Mülk / Müşteri</th>
                        <th className="px-6 py-4 font-semibold text-slate-700">Danışman</th>
                        <th className="px-6 py-4 font-semibold text-slate-700 text-right">Toplam Ciro</th>
                        <th className="px-6 py-4 font-semibold text-slate-700 text-right">Ofis Payı</th>
                        <th className="px-6 py-4 font-semibold text-slate-700 text-center">Durum</th>
                        <th className="px-6 py-4 font-semibold text-slate-700 text-right">İşlemler</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredTransactions.map(t => {
                        const consultant = consultants.find(c => c.id === t.consultantId);
                        return (
                            <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                                <td className="px-6 py-4 text-slate-500 whitespace-nowrap">
                                    {new Date(t.date).toLocaleDateString('tr-TR')}
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="font-bold text-slate-900">{t.propertyName}</span>
                                        <div className="flex items-center gap-2 mt-0.5">
                                            <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold uppercase ${t.type === TransactionType.SALE ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                                {t.type === TransactionType.SALE ? 'Satış' : 'Kiralama'}
                                            </span>
                                            <span className="text-xs text-slate-500 flex items-center gap-1">
                                                <UserIcon size={10} /> {t.customerName}
                                            </span>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">
                                    {consultant?.fullName || 'Silinmiş Danışman'}
                                </td>
                                <td className="px-6 py-4 text-right font-black text-slate-900 text-base">
                                    {formatCurrency(t.totalRevenue)}
                                </td>
                                <td className="px-6 py-4 text-right font-medium text-indigo-700">
                                    {formatCurrency(t.officeRevenue)}
                                </td>
                                <td className="px-6 py-4 text-center">
                                    {t.paymentStatus === PaymentStatus.PAID ? (
                                         <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 rounded-lg text-xs font-bold uppercase border border-emerald-200">
                                            <CheckCircle2 size={12} /> Hakediş Ödendi
                                         </span>
                                    ) : (
                                        <button 
                                            onClick={() => handleOpenPaymentModal(t)}
                                            className="inline-flex items-center gap-1 px-2 py-1 bg-amber-100 text-amber-700 hover:bg-amber-200 rounded-lg text-xs font-bold uppercase border border-amber-200 transition-colors"
                                            title="Hakediş Ödemesi Yap"
                                        >
                                            <Clock size={12} /> Bekliyor
                                        </button>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-2">
                                        <button 
                                            onClick={() => handleOpenPaymentModal(t)}
                                            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                                            title="Hakediş Formunu Görüntüle"
                                        >
                                            <FileText size={18} />
                                        </button>
                                        <button 
                                            onClick={() => handleDelete(t.id)}
                                            className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                            title="İşlemi Sil"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        );
                    })}
                    {filteredTransactions.length === 0 && (
                        <tr>
                            <td colSpan={7} className="px-6 py-12 text-center text-slate-500">
                                <div className="flex flex-col items-center gap-2">
                                    <Banknote size={32} className="text-slate-300" />
                                    <p>Henüz kayıtlı bir işlem bulunamadı.</p>
                                </div>
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Yeni İşlem Kaydı">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Mülk Adı / Tanımı</label>
            <input required placeholder="Örn: Vadi İstanbul 3+1 Daire" type="text" value={formData.propertyName} onChange={e => setFormData({...formData, propertyName: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Müşteri Adı Soyadı</label>
            <input required placeholder="Müşteri Adı" type="text" value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">İşlem Türü</label>
              <select value={formData.type} onChange={e => setFormData({...formData, type: e.target.value as TransactionType})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none">
                <option value={TransactionType.SALE}>Satış</option>
                <option value={TransactionType.RENT}>Kiralama</option>
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">İşlem Tarihi</label>
              <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none" />
            </div>
          </div>

          <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">İlgili Danışman</label>
              <select required value={formData.consultantId} onChange={e => setFormData({...formData, consultantId: e.target.value})} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none">
                <option value="">Seçiniz...</option>
                {consultants.map(c => <option key={c.id} value={c.id}>{c.fullName} (Komisyon: %{c.commissionRate})</option>)}
              </select>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Toplam Hizmet Bedeli (KDV Dahil)</label>
            <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-500 font-bold">₺</span>
                <input required type="number" min="0" value={formData.totalRevenue} onChange={e => setFormData({...formData, totalRevenue: e.target.value})} className="w-full pl-8 pr-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg outline-none text-lg font-bold" placeholder="0.00" />
            </div>
            <p className="text-[10px] text-slate-500 pt-1">Bu tutar üzerinden danışman hakedişi ve ofis payı otomatik hesaplanacaktır.</p>
          </div>

          <div className="pt-2">
            <button type="submit" className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold shadow-lg shadow-indigo-200 transition-all active:scale-95">Kaydı Tamamla</button>
          </div>
        </form>
      </Modal>

      <PaymentFormModal 
        isOpen={isPaymentModalOpen}
        onClose={() => setIsPaymentModalOpen(false)}
        transaction={selectedTransaction}
        consultant={selectedConsultant}
        onConfirmPayment={handleConfirmPayment}
      />
    </div>
  );
};

export default Transactions;
